import * as z from 'zod';
import { toTypedSchema } from '@vee-validate/zod';

export const schemaObject = {
  voice_verification_enabled: z.boolean({ message: 'Signatory verification setting is required' }),
  audio_saving_enabled: z.boolean({ message: 'Notes saving setting is required' }).optional().default(false),
  audio_expiration_days: z
    .number({
      message: 'Notes expiration days must be a number',
    })
    .int()
    .optional()
    .nullable()
    .default(null),
};

type VoiceVerificationData = z.infer<z.ZodObject<typeof schemaObject>>;

export function addVoiceVerificationIssues(data: VoiceVerificationData, ctx: z.RefinementCtx) {
  if (typeof data.voice_verification_enabled !== 'boolean') {
    ctx.addIssue({
      path: ['voice_verification_enabled'],
      code: z.ZodIssueCode.custom,
      message: 'Signatory verification must be defined',
    });
    return;
  }

  if (!data.voice_verification_enabled) return;

  if (typeof data.audio_saving_enabled !== 'boolean') {
    ctx.addIssue({
      path: ['audio_saving_enabled'],
      code: z.ZodIssueCode.custom,
      message: 'Notes saving enabled must be defined when signatory verification is enabled',
    });
    return;
  }

  if (!data.audio_saving_enabled) return;

  if (typeof data.audio_expiration_days !== 'number') {
    ctx.addIssue({
      path: ['audio_expiration_days'],
      code: z.ZodIssueCode.custom,
      message: 'Notes expiration days must be set when notes saving is enabled',
    });
  }
}

export const formSchema = toTypedSchema(
  z.object(schemaObject).superRefine((data, ctx) => addVoiceVerificationIssues(data, ctx))
);
