import * as z from 'zod';

export const schemaObject = {
  contract_template_local: z.string().optional(),
  contract_template_quick_response_force: z.string().optional(),
  use_separate_qrf_template: z.boolean().optional(),
  contract_sending_enabled: z.boolean().optional(),
};

type ContractTemplateData = z.infer<z.ZodObject<typeof schemaObject>>;

export interface ContractTemplateIssuesOptions {
  // Provider-deleted template ids. A selection matching one of these is rejected so
  // the user is forced to pick a template that still exists on the provider's side.
  deletedTemplateIds?: Set<string>;
}

export function addContractTemplateIssues(
  data: ContractTemplateData,
  ctx: z.RefinementCtx,
  { deletedTemplateIds }: ContractTemplateIssuesOptions = {}
) {
  if (!data.contract_sending_enabled) return;
  if (!data.contract_template_local) {
    ctx.addIssue({
      path: ['contract_template_local'],
      code: z.ZodIssueCode.custom,
      message: 'Contract Template is required',
    });
  } else if (deletedTemplateIds?.has(data.contract_template_local)) {
    ctx.addIssue({
      path: ['contract_template_local'],
      code: z.ZodIssueCode.custom,
      message: "Selected contract template was deleted on the provider's side. Select a new one.",
    });
  }
  if (data.use_separate_qrf_template) {
    if (!data.contract_template_quick_response_force) {
      ctx.addIssue({
        path: ['contract_template_quick_response_force'],
        code: z.ZodIssueCode.custom,
        message: 'QRF Contract Template is required when using a different template',
      });
    } else if (deletedTemplateIds?.has(data.contract_template_quick_response_force)) {
      ctx.addIssue({
        path: ['contract_template_quick_response_force'],
        code: z.ZodIssueCode.custom,
        message: "Selected QRF contract template was deleted on the provider's side. Select a new one.",
      });
    }
  }
}
