import * as z from 'zod';
import { toTypedSchema } from '@vee-validate/zod';
import { numericString } from './utils';

const schemaPaymentEnabled = {
  payments_enabled: z.boolean({
    invalid_type_error: 'Payment Enabled must be a boolean',
  }),
};

const schemaIncreasedPayRateEnabled = {
  increased_pay_rate_enabled: z
    .boolean({
      invalid_type_error: 'Increased Pay Rate Enabled must be a boolean',
    })
    .optional(),
};

const schemaEarningReviewHours = {
  earning_review_hours: numericString('Earning Review Hours', { min: 0, integer: true, max: 300, required: true }),
};

export const schemaObjectSignatures = {
  ...schemaPaymentEnabled,
  ...schemaEarningReviewHours,
  for_canvasser_per_signature: numericString('Payment Amount Per Signature', { min: 0, max: 200 }),
  for_client_per_signature: numericString('Charge Amount Per Signature', { min: 0, max: 200 }),
  qrf_for_canvasser_per_signature: numericString('QRF For Canvasser Per Signature', { min: 0, max: 200 }),
};

export const formSchemaSignature = toTypedSchema(z.object(schemaObjectSignatures));

export const schemaObjectCanvassing = {
  ...schemaPaymentEnabled,
  ...schemaIncreasedPayRateEnabled,
  ...schemaEarningReviewHours,
  for_canvasser_per_hour: numericString('Payment Per Hour', { min: 0, max: 200 }),
  qrf_for_canvasser_per_hour: numericString('QRF For Canvasser Per Hour', {
    min: 0,
    max: 200,
  }),
  allowed_break_minutes_per_hour: numericString('Allowed Breaks Per Hour', {
    required: true,
    min: 0,
    max: 60,
    integer: true,
  }),
  grace_allowance_minutes: numericString('Grace Allowance Minutes', {
    required: true,
    min: 0,
    max: 60,
    integer: true,
  }),
  walk_speed_mph: numericString('Walking Speed', { required: true, positive: true }),
  drive_speed_mph: numericString('Driving Speed', { required: true, positive: true }),
  increased_for_canvasser_per_hour: numericString('Increased Payment Per Hour', {
    min: 0,
    max: 300,
  }),
  increased_qrf_for_canvasser_per_hour: numericString('Increased QRF Payment Per Hour', {
    min: 0,
    max: 300,
  }),
  increased_pay_rate_threshold_in_hours: numericString('Increased Pay Rate Threshold', {
    min: 0,
    max: 24,
    integer: true,
  }),
};

export const formSchemaCanvassing = toTypedSchema(z.object(schemaObjectCanvassing));

type CanvassingPaymentData = z.infer<z.ZodObject<typeof schemaObjectCanvassing>>;

function requirePositive(ctx: z.RefinementCtx, value: number | undefined, field: string, label: string) {
  if (typeof value !== 'number') {
    ctx.addIssue({
      path: [field],
      code: z.ZodIssueCode.custom,
      message: `${label} is required when Payment is enabled`,
    });
  } else if (value <= 0) {
    ctx.addIssue({
      path: [field],
      code: z.ZodIssueCode.custom,
      message: `${label} should be greater than 0`,
    });
  }
}

function requireGteBase(
  ctx: z.RefinementCtx,
  value: number | undefined,
  baseValue: number | undefined,
  field: string,
  label: string,
  baseLabel: string
) {
  if (typeof value !== 'number') {
    ctx.addIssue({
      path: [field],
      code: z.ZodIssueCode.custom,
      message: `${label} is required when Payment is enabled`,
    });
  } else if (typeof baseValue === 'number' && value < baseValue) {
    ctx.addIssue({
      path: [field],
      code: z.ZodIssueCode.custom,
      message: `${label} should be greater than or equal to ${baseLabel}`,
    });
  }
}

export function addCanvassingPaymentIssues(data: CanvassingPaymentData, ctx: z.RefinementCtx) {
  if (!data.payments_enabled) return;

  requirePositive(ctx, data.for_canvasser_per_hour, 'for_canvasser_per_hour', 'Payment Per Hour');
  requirePositive(ctx, data.qrf_for_canvasser_per_hour, 'qrf_for_canvasser_per_hour', 'QRF For Canvasser Per Hour');
  requirePositive(ctx, data.earning_review_hours, 'earning_review_hours', 'Earning Review Hours');
  requirePositive(
    ctx,
    data.allowed_break_minutes_per_hour,
    'allowed_break_minutes_per_hour',
    'Allowed Breaks Per Hour'
  );

  if (!data.increased_pay_rate_enabled) return;

  requireGteBase(
    ctx,
    data.increased_for_canvasser_per_hour,
    data.for_canvasser_per_hour,
    'increased_for_canvasser_per_hour',
    'Increased Payment Per Hour',
    'Payment Per Hour'
  );
  requireGteBase(
    ctx,
    data.increased_qrf_for_canvasser_per_hour,
    data.qrf_for_canvasser_per_hour,
    'increased_qrf_for_canvasser_per_hour',
    'Increased QRF Payment Per Hour',
    'QRF Payment Per Hour'
  );
  requirePositive(
    ctx,
    data.increased_pay_rate_threshold_in_hours,
    'increased_pay_rate_threshold_in_hours',
    'Increased Pay Rate Threshold'
  );
}

type SignaturePaymentData = z.infer<z.ZodObject<typeof schemaObjectSignatures>>;

export function addSignaturePaymentIssues(data: SignaturePaymentData, ctx: z.RefinementCtx) {
  if (!data.payments_enabled) return;

  requirePositive(ctx, data.for_canvasser_per_signature, 'for_canvasser_per_signature', 'Payment Amount Per Signature');
  requirePositive(ctx, data.for_client_per_signature, 'for_client_per_signature', 'Charge Amount Per Signature');
  requirePositive(
    ctx,
    data.qrf_for_canvasser_per_signature,
    'qrf_for_canvasser_per_signature',
    'QRF For Canvasser Per Signature'
  );
  requirePositive(ctx, data.earning_review_hours, 'earning_review_hours', 'Earning Review Hours');

  if (
    !data.for_canvasser_per_signature ||
    !data.for_client_per_signature ||
    data.for_canvasser_per_signature >= data.for_client_per_signature
  ) {
    ctx.addIssue({
      path: ['for_canvasser_per_signature'],
      code: z.ZodIssueCode.custom,
      message: 'Payment Amount Per Signature must be less than Charge Amount Per Signature',
    });
  }
}
