<template>
  <div class="flex flex-col">
    <ProjectEditConfigurationFieldRow
      label="Contracts Enabled"
      description="When on, canvassers are sent a contract to sign during onboarding."
    >
      <FormItemWrapper name="contract_sending_enabled" is-no-message row slot-wrapper-class="sm:items-end">
        <Switch
          id="contract_sending_enabled"
          :model-value="!!contractSendingEnabled"
          @update:model-value="(value) => handleContractSendingChange(value)"
        />
      </FormItemWrapper>
    </ProjectEditConfigurationFieldRow>

    <template v-if="contractSendingEnabled">
      <ProjectEditConfigurationFieldRow
        label="Contract Template"
        description="Default contract used for canvassers on this project."
      >
        <FormItemWrapper name="contract_template_local" slot-wrapper-class="sm:items-end">
          <template #default="{ slots }">
            <div class="flex items-center gap-2">
              <TooltipProvider v-if="isLocalTemplateDeleted">
                <Tooltip>
                  <TooltipTrigger as-child>
                    <span data-testid="project-config-contract-template-deleted-warning">
                      <AlertTriangle class="size-5 shrink-0 text-warning-foreground" />
                    </span>
                  </TooltipTrigger>
                  <TooltipContent>
                    Contract template was deleted on the provider's side, select a new one from the list.
                  </TooltipContent>
                </Tooltip>
              </TooltipProvider>
              <KitFormsSelect
                id="contract_template_local"
                :items="localTemplates"
                :component-field="slots.componentField"
                :loading="isLoading"
                :disabled="isSyncing"
                :error="error ? error.data?.detail || 'Failed to load contract templates' : ''"
                trigger-class="w-full sm:w-72"
              />
              <Button
                type="button"
                variant="outline"
                size="icon"
                :prepend-icon="isSyncing || isLoading ? undefined : RefreshCw"
                :loading="isSyncing || isLoading"
                title="Re-sync templates from SignWell"
                data-testid="project-config-sync-contract-template"
                @click="syncContracts({ provider: provider })"
              />
            </div>
          </template>
        </FormItemWrapper>
      </ProjectEditConfigurationFieldRow>

      <ProjectEditConfigurationFieldRow
        label="Different Template for Quick Response Force"
        description="Use a separate contract for QRF assignments instead of the default template."
      >
        <FormItemWrapper name="use_separate_qrf_template" is-no-message row slot-wrapper-class="sm:items-end">
          <Switch
            id="use_separate_qrf_template"
            :model-value="!!useSeparateQrfTemplate"
            @update:model-value="(value) => handleSwitchChange(value)"
          />
        </FormItemWrapper>
      </ProjectEditConfigurationFieldRow>

      <ProjectEditConfigurationFieldRow
        v-if="useSeparateQrfTemplate"
        label="QRF Contract Template"
        description="Contract used specifically for QRF dispatches."
      >
        <FormItemWrapper name="contract_template_quick_response_force" slot-wrapper-class="sm:items-end">
          <template #default="{ slots }">
            <div class="flex items-center gap-2">
              <TooltipProvider v-if="isQrfTemplateDeleted">
                <Tooltip>
                  <TooltipTrigger as-child>
                    <span data-testid="project-config-qrf-contract-template-deleted-warning">
                      <AlertTriangle class="size-5 shrink-0 text-warning-foreground" />
                    </span>
                  </TooltipTrigger>
                  <TooltipContent>
                    Contract template was deleted on the provider's side, select a new one from the list.
                  </TooltipContent>
                </Tooltip>
              </TooltipProvider>
              <KitFormsSelect
                id="contract_template_quick_response_force"
                :items="qrfTemplates"
                :component-field="slots.componentField"
                :loading="isLoading"
                :disabled="isSyncing"
                :error="error ? error.data?.detail || 'Failed to load contract templates' : ''"
                trigger-class="w-full sm:w-72"
              />
              <Button
                type="button"
                variant="outline"
                size="icon"
                :prepend-icon="isSyncing || isLoading ? undefined : RefreshCw"
                :loading="isSyncing || isLoading"
                title="Re-sync templates from SignWell"
                data-testid="project-config-sync-qrf-contract-template"
                @click="syncContracts({ provider: provider })"
              />
            </div>
          </template>
        </FormItemWrapper>
      </ProjectEditConfigurationFieldRow>
    </template>
  </div>
</template>

<script setup lang="ts">
import { useField } from 'vee-validate';
import { AlertTriangle, RefreshCw } from 'lucide-vue-next';
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from '~/components/ui/tooltip';
import { useSelectorContractTemplates } from '~/queries/selectors/contractTemplates';
import { syncContractsTemplates } from '~/client';

interface Props {
  deletedTemplates?: { id: string; name: string }[];
}

const props = withDefaults(defineProps<Props>(), {
  deletedTemplates: () => [],
});

const { contractTemplates, refetch, isLoading, error, provider } = useSelectorContractTemplates();

const { value: useSeparateQrfTemplate, setValue: setUseSeparateQrfTemplate } =
  useField<boolean>('use_separate_qrf_template');
const { value: qrfTemplate, setValue: setQrfTemplate } = useField<string | undefined>(
  'contract_template_quick_response_force'
);
const { value: contractTemplateLocal, setValue: setContractTemplateLocal } = useField<string | undefined>(
  'contract_template_local'
);
const { value: contractSendingEnabled, setValue: setContractSendingEnabled } =
  useField<boolean>('contract_sending_enabled');

const deletedTemplateIds = computed(() => new Set(props.deletedTemplates.map((t) => t.id)));
const isLocalTemplateDeleted = computed(
  () => !!contractTemplateLocal.value && deletedTemplateIds.value.has(contractTemplateLocal.value)
);
const isQrfTemplateDeleted = computed(() => !!qrfTemplate.value && deletedTemplateIds.value.has(qrfTemplate.value));

const templateItems = computed<SelectItem<string>[]>(() =>
  contractTemplates.value.map((item) => ({ name: item.name, value: item.value }))
);

function withDeletedSelection(selectedId: string | undefined) {
  const present = new Set(templateItems.value.map((i) => i.value));
  const injected = props.deletedTemplates
    .filter((t) => !present.has(t.id) && t.id === selectedId)
    .map((t) => ({ name: t.name, value: t.id }));
  return [...injected, ...templateItems.value];
}
const localTemplates = computed(() => withDeletedSelection(contractTemplateLocal.value));
const qrfTemplates = computed(() => withDeletedSelection(qrfTemplate.value));

const { mutateAsync: syncContracts, isLoading: isSyncing } = useMutation({
  mutation: (
    body: import('~/client').ContractTemplateSyncApiRequest
  ): Promise<import('~/client').ContractTemplateSyncApiResponse> =>
    syncContractsTemplates({
      composable: '$fetch',
      body,
    }),
  onSuccess: () => {
    refetch();
    showToastSuccess('Contracts synced');
  },
  onError: (error) => {
    refetch();
    showToastError(error);
  },
});

function handleSwitchChange(value: boolean) {
  setUseSeparateQrfTemplate(value);
  if (!value) setQrfTemplate(undefined);
}

function handleContractSendingChange(value: boolean) {
  setContractSendingEnabled(value);
  if (!value) {
    handleSwitchChange(false);
    setContractTemplateLocal(undefined);
  }
}
</script>
