<template>
  <AppLoader v-if="isLoading" subject="project configuration" />
  <AppError v-else-if="error" :error="error" title="Failed to load project configuration" />
  <AppEmpty v-else-if="!projectConfiguration" subject="project configuration" />
  <ProjectEditConfigurationFormSignature
    v-else-if="projectConfiguration?.type === 'signature'"
    :project-id="projectId"
    :status="projectConfiguration.status"
    :data="signatureProjectConfiguration"
  />
  <ProjectEditConfigurationFormCanvassing
    v-else-if="projectConfiguration?.type === 'canvassing'"
    :project-id="projectId"
    :status="projectConfiguration.status"
    :data="canvassingProjectConfiguration"
  />
</template>

<script lang="ts" setup>
import { useProjectConfiguration } from '~/queries/project/edit/configuration';
import type { SignatureProjectConfiguration, CanvassingProjectConfiguration } from '~/types/projects/configuration';

definePageMeta({
  backGroup: 'project-edit',
  roles: ['admin'],
  backLabel: 'project edit',
});

useSeoMeta({
  title: computed(() => 'Edit Project'),
  description: computed(() => 'Edit your project configuration here.'),
});

const { projectConfiguration, isLoading, error, projectId } = useProjectConfiguration();

const signatureProjectConfiguration = computed<SignatureProjectConfiguration | undefined>(() => {
  return projectConfiguration.value &&
    isSignaturePricing(projectConfiguration.value.pricing) &&
    projectConfiguration.value.voice_verification_enabled !== undefined &&
    projectConfiguration.value.audio_saving_enabled !== undefined &&
    projectConfiguration.value.audio_expiration_days !== undefined
    ? {
        voice_verification_enabled: projectConfiguration.value.voice_verification_enabled,
        audio_saving_enabled: projectConfiguration.value.audio_saving_enabled,
        audio_expiration_days: projectConfiguration.value.audio_expiration_days,
        pricing: projectConfiguration.value.pricing,
        staffing: projectConfiguration.value.staffing,
        budget: projectConfiguration.value.budget,
        contract_configs: projectConfiguration.value.contract_configs,
        contract_sending_enabled: projectConfiguration.value.contract_sending_enabled,
      }
    : undefined;
});

const canvassingProjectConfiguration = computed<CanvassingProjectConfiguration | undefined>(() => {
  return projectConfiguration.value && isCanvassingPricing(projectConfiguration.value.pricing)
    ? {
        pricing: projectConfiguration.value.pricing,
        staffing: projectConfiguration.value.staffing,
        budget: projectConfiguration.value.budget,
        canvassing_application_ids: projectConfiguration.value.canvassing_application_ids,
        canvassing_application_name: projectConfiguration.value.canvassing_application_name,
        canvassing_application_config: projectConfiguration.value.canvassing_application_config,
        survey_goal_percentage: projectConfiguration.value.survey_goal_percentage,
        audio_recording: projectConfiguration.value?.audio_recording_config?.permission || null,
        restricted_zip_codes: projectConfiguration.value?.audio_recording_config?.restricted_zip_codes || null,
        voter_redaction_enabled: projectConfiguration.value?.audio_recording_config?.voter_redaction_enabled ?? false,
        contract_configs: projectConfiguration.value.contract_configs,
        contract_sending_enabled: projectConfiguration.value.contract_sending_enabled,
      }
    : undefined;
});

onBeforeUnmount(() => {
  const queryCache = useQueryCache();
  queryCache.setQueryData(['project-configuration', projectId.value], undefined);
});
</script>

<style lang="scss" scoped></style>
