<template>
  <ProjectEditConfigurationFieldRow
    label="Enable Signatory Verifications"
    description="Confirm each signature during capture."
  >
    <FormItemWrapper name="voice_verification_enabled" is-no-message row>
      <Switch
        id="voice_verification_enabled"
        :model-value="values.voice_verification_enabled"
        @update:model-value="onVoiceVerificationChange"
      />
    </FormItemWrapper>
  </ProjectEditConfigurationFieldRow>
  <ProjectEditConfigurationFieldRow
    v-if="values.voice_verification_enabled"
    label="Save Notes"
    description="Keep notes after verification, instead of discarding them immediately."
  >
    <FormItemWrapper name="audio_saving_enabled" is-no-message row>
      <Switch
        id="audio_saving_enabled"
        :model-value="values.audio_saving_enabled"
        @update:model-value="onAudioSavingChange"
      />
    </FormItemWrapper>
  </ProjectEditConfigurationFieldRow>
  <ProjectEditConfigurationFieldRow
    v-if="values.audio_saving_enabled"
    label="Expire Notes In"
    description="How many days notes are retained before automatic deletion."
  >
    <FormItemWrapper name="audio_expiration_days" slot-wrapper-class="sm:items-end">
      <template #default="{ slots }">
        <KitFormsSelect
          id="audio_expiration_days"
          :items="expireVoiceInDays"
          :component-field="slots.componentField"
          trigger-class="w-full sm:w-72"
        />
      </template>
    </FormItemWrapper>
  </ProjectEditConfigurationFieldRow>
</template>

<script setup lang="ts">
import { useFormContext } from 'vee-validate';
import { expireVoiceInDays } from '~/constants/projects/expireVoiceInDays';

const { values, setFieldValue } = useFormContext();

function onVoiceVerificationChange(value: boolean) {
  setFieldValue('voice_verification_enabled', value, false);
  setFieldValue('audio_saving_enabled', false, false);
}

function onAudioSavingChange(value: boolean) {
  setFieldValue('audio_saving_enabled', value, false);
  setFieldValue('audio_expiration_days', 1, false);
}
</script>
