<template>
  <ProjectEditConfigurationFieldRow
    label="Payment Enabled"
    description="Turn on to start paying canvassers based on the rates below."
    row-class="!border-b-0"
  >
    <FormItemWrapper name="payments_enabled" is-no-message row slot-wrapper-class="sm:items-end">
      <Switch
        id="payments_enabled"
        :model-value="values.payments_enabled"
        @update:model-value="onPaymentsEnabledChange"
      />
    </FormItemWrapper>
  </ProjectEditConfigurationFieldRow>

  <div v-if="values.payments_enabled" class="pt-4 mt-2 border-t">
    <div class="text-xs uppercase tracking-wide font-semibold text-muted-foreground mb-2">Base pay</div>

    <ProjectEditConfigurationFieldRow
      label="Per Hour, $"
      description="Standard hourly rate paid for approved work-shift time."
    >
      <FormItemWrapper name="for_canvasser_per_hour" slot-wrapper-class="sm:items-end">
        <template #default="{ slots }">
          <MoneyInput id="for_canvasser_per_hour" class="w-32 text-right" v-bind="slots.componentField" />
        </template>
      </FormItemWrapper>
    </ProjectEditConfigurationFieldRow>

    <ProjectEditConfigurationFieldRow
      label="QRF Per Hour, $"
      description="Higher rate for Quick Response Force dispatches (short-notice shift backfills)."
    >
      <FormItemWrapper name="qrf_for_canvasser_per_hour" slot-wrapper-class="sm:items-end">
        <template #default="{ slots }">
          <MoneyInput id="qrf_for_canvasser_per_hour" class="w-32 text-right" v-bind="slots.componentField" />
        </template>
      </FormItemWrapper>
    </ProjectEditConfigurationFieldRow>
  </div>

  <div v-if="values.payments_enabled" class="pt-4 mt-2 border-t">
    <div class="text-xs uppercase tracking-wide font-semibold text-muted-foreground mb-2">Increased pay rate</div>

    <ProjectEditConfigurationFieldRow
      label="Enable Increased Rate After Threshold"
      description="Enable a higher rate after a canvasser passes an hours threshold. Only affects new assignments; existing assignments keep their values."
    >
      <FormItemWrapper name="increased_pay_rate_enabled" is-no-message row slot-wrapper-class="sm:items-end">
        <Switch
          id="increased_pay_rate_enabled"
          :model-value="values.increased_pay_rate_enabled"
          @update:model-value="onIncreasedPayRateEnabledChange"
        />
      </FormItemWrapper>
    </ProjectEditConfigurationFieldRow>

    <template v-if="values.increased_pay_rate_enabled">
      <ProjectEditConfigurationFieldRow
        label="Increased Per Hour, $"
        description="Hourly rate after the threshold is reached."
      >
        <FormItemWrapper name="increased_for_canvasser_per_hour" slot-wrapper-class="sm:items-end">
          <template #default="{ slots }">
            <MoneyInput id="increased_for_canvasser_per_hour" class="w-32 text-right" v-bind="slots.componentField" />
          </template>
        </FormItemWrapper>
      </ProjectEditConfigurationFieldRow>

      <ProjectEditConfigurationFieldRow
        label="Increased QRF Per Hour, $"
        description="QRF rate after the threshold is reached."
      >
        <FormItemWrapper name="increased_qrf_for_canvasser_per_hour" slot-wrapper-class="sm:items-end">
          <template #default="{ slots }">
            <MoneyInput
              id="increased_qrf_for_canvasser_per_hour"
              class="w-32 text-right"
              v-bind="slots.componentField"
            />
          </template>
        </FormItemWrapper>
      </ProjectEditConfigurationFieldRow>

      <ProjectEditConfigurationFieldRow
        label="Threshold, hours"
        description="Total hours worked at which the increased rate takes effect."
      >
        <FormItemWrapper name="increased_pay_rate_threshold_in_hours" slot-wrapper-class="sm:items-end">
          <template #default="{ slots }">
            <Input
              id="increased_pay_rate_threshold_in_hours"
              v-maska
              type="string"
              inputmode="numeric"
              data-maska-number-fraction="0"
              data-maska-number
              class="w-32 text-right"
              v-bind="slots.componentField"
            />
          </template>
        </FormItemWrapper>
      </ProjectEditConfigurationFieldRow>
    </template>
  </div>

  <div class="pt-4 mt-2 border-t">
    <div class="text-xs uppercase tracking-wide font-semibold text-muted-foreground mb-2">Time &amp; breaks</div>

    <ProjectEditConfigurationFieldRow
      label="Earning Review Hours"
      description="Hours after a shift during which earnings can be reviewed and adjusted."
    >
      <FormItemWrapper name="earning_review_hours" slot-wrapper-class="sm:items-end">
        <template #default="{ slots }">
          <Input
            id="earning_review_hours"
            v-maska
            type="string"
            inputmode="numeric"
            data-maska-number-fraction="0"
            data-maska-number
            class="w-32 text-right"
            v-bind="slots.componentField"
          />
        </template>
      </FormItemWrapper>
    </ProjectEditConfigurationFieldRow>

    <ProjectEditConfigurationFieldRow
      label="Allowed Breaks Per Hour, min"
      description="Minutes of break a canvasser may take per hour worked without affecting earnings."
    >
      <FormItemWrapper name="allowed_break_minutes_per_hour" slot-wrapper-class="sm:items-end">
        <template #default="{ slots }">
          <Input
            id="allowed_break_minutes_per_hour"
            v-maska
            type="string"
            inputmode="numeric"
            data-maska-number-fraction="0"
            data-maska-number
            class="w-32 text-right"
            v-bind="slots.componentField"
          />
        </template>
      </FormItemWrapper>
    </ProjectEditConfigurationFieldRow>

    <ProjectEditConfigurationFieldRow
      label="Grace Allowance, min"
      description="Minutes of inactivity tolerated before a shift is auto-paused."
    >
      <FormItemWrapper name="grace_allowance_minutes" slot-wrapper-class="sm:items-end">
        <template #default="{ slots }">
          <Input
            id="grace_allowance_minutes"
            v-maska
            type="string"
            inputmode="numeric"
            data-maska-number-fraction="0"
            data-maska-number
            class="w-32 text-right"
            v-bind="slots.componentField"
          />
        </template>
      </FormItemWrapper>
    </ProjectEditConfigurationFieldRow>

    <ProjectEditConfigurationFieldRow
      label="Walking Speed, mph"
      description="Assumed walking speed between nearby interactions, used to compute travel-time allowance in break calculation."
    >
      <FormItemWrapper name="walk_speed_mph" slot-wrapper-class="sm:items-end">
        <template #default="{ slots }">
          <Input
            id="walk_speed_mph"
            v-maska
            type="string"
            inputmode="decimal"
            data-maska-number-fraction="2"
            data-maska-number
            class="w-32 text-right"
            v-bind="slots.componentField"
          />
        </template>
      </FormItemWrapper>
    </ProjectEditConfigurationFieldRow>

    <ProjectEditConfigurationFieldRow
      label="Driving Speed, mph"
      description="Assumed driving speed for gaps over half a mile between interactions."
    >
      <FormItemWrapper name="drive_speed_mph" slot-wrapper-class="sm:items-end">
        <template #default="{ slots }">
          <Input
            id="drive_speed_mph"
            v-maska
            type="string"
            inputmode="decimal"
            data-maska-number-fraction="2"
            data-maska-number
            class="w-32 text-right"
            v-bind="slots.componentField"
          />
        </template>
      </FormItemWrapper>
    </ProjectEditConfigurationFieldRow>
  </div>
</template>

<script setup lang="ts">
import { useFormContext } from 'vee-validate';
import type { CanvassingProjectPricing } from '~/client';

interface Props {
  savedPricing: CanvassingProjectPricing | undefined;
}
const props = defineProps<Props>();

const { values, setFieldValue } = useFormContext();

function setIncreasedFieldsFromProps(enabled: boolean) {
  setFieldValue(
    'increased_for_canvasser_per_hour',
    enabled ? props.savedPricing?.increased_for_canvasser_per_hour?.toString() || undefined : undefined,
    false
  );
  setFieldValue(
    'increased_qrf_for_canvasser_per_hour',
    enabled ? props.savedPricing?.increased_qrf_for_canvasser_per_hour?.toString() || undefined : undefined,
    false
  );
  setFieldValue(
    'increased_pay_rate_threshold_in_hours',
    enabled ? props.savedPricing?.increased_pay_rate_threshold_in_hours?.toString() || undefined : undefined,
    false
  );
}

function onPaymentsEnabledChange(value: boolean) {
  setFieldValue('payments_enabled', value, false);
  const increasedEnabled = value ? (props.savedPricing?.increased_pay_rate_enabled ?? false) : false;
  setFieldValue('increased_pay_rate_enabled', increasedEnabled, false);
  setIncreasedFieldsFromProps(increasedEnabled);
}

function onIncreasedPayRateEnabledChange(value: boolean) {
  setFieldValue('increased_pay_rate_enabled', value, false);
  setIncreasedFieldsFromProps(value);
}
</script>
