import type { MaybeRefOrGetter } from 'vue';
import { getSelectorI360PrefixList } from '~/client';
import type { CanvassingApplicationName, PrefixSelectorResponse } from '~/client';

export const useSelectorCanvassingPrefixList = (
  appName: MaybeRefOrGetter<CanvassingApplicationName>,
  enabled: MaybeRefOrGetter<boolean>
) => {
  const { data, isLoading, error } = useQuery({
    key: () => ['selector-canvassing-prefix-list', toValue(appName)],
    query: (): Promise<PrefixSelectorResponse> =>
      getSelectorI360PrefixList({ composable: '$fetch', query: { app_name: toValue(appName) } }),
    enabled: () => toValue(enabled),
  });

  return {
    prefixes: computed(() => data.value?.items ?? []),
    isLoading,
    error,
  };
};

// Backward-compatible wrapper (i360-only).
export const useSelectorI360PrefixList = (enabled: MaybeRefOrGetter<boolean>) =>
  useSelectorCanvassingPrefixList('i360', enabled);
