<template>
  <ProjectEditConfigurationFieldRow
    label="Note-taking Permission"
    description="Controls whether canvassers take notes on conversations and whether any geographic restrictions apply."
  >
    <FormItemWrapper name="audio_recording" slot-wrapper-class="sm:items-end">
      <template #default="{ slots }">
        <KitFormsSelect
          id="audio_recording"
          :items="voiceRecordingItems"
          :component-field="slots.componentField"
          trigger-class="w-full sm:w-72"
          @update:model-value="onAudioRecordingChange"
        />
      </template>
    </FormItemWrapper>
  </ProjectEditConfigurationFieldRow>

  <ProjectEditConfigurationFieldRow
    v-if="values.audio_recording === 'full_recording_with_restricted_area'"
    label="Restricted ZIP Codes"
    description="ZIP codes where note-taking is suppressed (e.g., legal restrictions)."
  >
    <FormItemWrapper name="restricted_zip_codes" slot-wrapper-class="sm:items-end">
      <template #default="{ slots }">
        <KitFormsComboboxMultiple
          v-if="getVoterDBAvailability()"
          id="restricted_zip_codes"
          placeholder="Select ZIP Codes"
          :items="processedZipCodes"
          :component-field="slots.componentField"
          :loading="zipCodesLoading"
          :disabled="false"
          :null-is-all="false"
          :error="zipCodesError ? zipCodesError?.data?.detail || 'Failed to load zipCodes' : ''"
          empty-text="No ZIP codes found."
          :max-items-in-input="width > 440 ? 4 : 2"
          element-width="w-full sm:w-72"
        />
        <Alert v-else>
          <InfoIcon />
          <AlertTitle>No Uploaded Voter Database</AlertTitle>
          <AlertDescription> Import a voter database to see and configure restricted ZIP code areas. </AlertDescription>
        </Alert>
      </template>
    </FormItemWrapper>
  </ProjectEditConfigurationFieldRow>

  <ProjectEditConfigurationFieldRow
    v-if="values.audio_recording && values.audio_recording !== 'no_recording'"
    label="Redact Voter Voice"
    description="Replaces the voter's speech with silence and keeps only the canvasser's side of the transcript. For two-party consent states."
  >
    <FormItemWrapper name="voter_redaction_enabled" is-no-message row slot-wrapper-class="sm:items-end">
      <Switch
        id="voter_redaction_enabled"
        :model-value="values.voter_redaction_enabled"
        @update:model-value="onVoterRedactionChange"
      />
    </FormItemWrapper>
  </ProjectEditConfigurationFieldRow>
</template>

<script setup lang="ts">
import { InfoIcon } from 'lucide-vue-next';
import { useFormContext } from 'vee-validate';
import { voiceRecordingItems } from '~/constants/projects/voiceRecordingConfig';
import { getListOfZipCodes } from '~/client';
import type { ProjectEditTabsStatusResponse } from '~/client';

interface Props {
  projectId: string;
  savedRestrictedZipCodes: string[] | null | undefined;
}
const props = defineProps<Props>();

const { values, setFieldValue } = useFormContext();

function onAudioRecordingChange() {
  const dataToSet =
    values.audio_recording === 'full_recording_with_restricted_area'
      ? props.savedRestrictedZipCodes || undefined
      : undefined;
  setFieldValue('restricted_zip_codes', dataToSet, false);

  // There is nothing to redact without note-taking, and the backend rejects the combination.
  if (values.audio_recording === 'no_recording') {
    setFieldValue('voter_redaction_enabled', false, false);
  }
}

function onVoterRedactionChange(value: boolean) {
  setFieldValue('voter_redaction_enabled', value, false);
}

const {
  data: zipCodes,
  isLoading: zipCodesLoading,
  error: zipCodesError,
} = useQuery({
  key: () => ['selector-zip-codes', props.projectId, { type: values?.audio_recording }],
  query: () => getListOfZipCodes({ composable: '$fetch', path: { project_id: props.projectId } }),
  enabled: () => !!props.projectId && values?.audio_recording === 'full_recording_with_restricted_area',
});

const processedZipCodes = computed<SelectItem[]>(() => {
  return (
    zipCodes.value?.items?.map((item) => ({
      name: item,
      value: item,
    })) || []
  );
});

const { width } = useWindowSize();

function getVoterDBAvailability() {
  const queryCache = useQueryCache();
  const tabStatuses = queryCache.getQueryData<ProjectEditTabsStatusResponse>([
    'project-edit-tabs-status',
    props.projectId,
  ]);
  if (tabStatuses) return tabStatuses.voter_database === 'success';
  else return null;
}
</script>
