import { getProjectConfig } from '~/client';

export const useProjectConfiguration = defineQuery(() => {
  const route = useRoute('projects-id-edit-general-information');
  const projectId = computed(() => route.params?.id);

  const {
    data: projectConfiguration,
    error,
    isLoading,
  } = useQuery({
    key: () => ['project-configuration', projectId.value],
    query: () => getProjectConfig({ composable: '$fetch', path: { project_id: projectId.value } }),
    staleTime: 0,
    enabled: () => useRoute().name === 'projects-id-edit-project-configuration' && !!projectId.value,
  });

  return {
    projectId,
    projectConfiguration,
    error,
    isLoading,
  };
});
