import * as z from 'zod';
import { toTypedSchema } from '@vee-validate/zod';
import type { AudioRecordingConfig, AudioRecordingPermission } from '~/client';

export interface VoiceRecordingOptions {
  isDraft: boolean;
}

export const schemaObject = {
  audio_recording: z
    .string()
    .optional()
    .transform((val) => (val ? (val as AudioRecordingPermission) : undefined)),
  restricted_zip_codes: z.array(z.string()).optional(),
  // Orthogonal to the permission: composes with restricted areas, which a fourth
  // AudioRecordingPermission value could not express.
  voter_redaction_enabled: z.boolean().optional(),
};

type VoiceRecordingData = z.infer<z.ZodObject<typeof schemaObject>>;

export function addVoiceRecordingIssues(
  data: VoiceRecordingData,
  ctx: z.RefinementCtx,
  { isDraft }: VoiceRecordingOptions
) {
  if (isDraft) return;

  if (!data.audio_recording) {
    ctx.addIssue({
      path: ['audio_recording'],
      code: z.ZodIssueCode.custom,
      message: 'Note-taking Permission is required',
    });
    return;
  }

  if (
    data.audio_recording === 'full_recording_with_restricted_area' &&
    (!data.restricted_zip_codes || data.restricted_zip_codes.length === 0)
  ) {
    ctx.addIssue({
      path: ['restricted_zip_codes'],
      code: z.ZodIssueCode.custom,
      message: 'At least one restricted ZIP code should be provided',
    });
  }

  // Mirrors validate_audio_config on the backend: there is no audio to redact.
  if (data.voter_redaction_enabled && data.audio_recording === 'no_recording') {
    ctx.addIssue({
      path: ['voter_redaction_enabled'],
      code: z.ZodIssueCode.custom,
      message: 'Voter redaction requires note-taking to be enabled',
    });
  }
}

export function buildVoiceRecordingPayload(values: VoiceRecordingData): {
  audio_recording_config: AudioRecordingConfig | null;
} {
  if (!values.audio_recording) {
    return { audio_recording_config: null };
  }
  return {
    audio_recording_config: {
      permission: values.audio_recording,
      restricted_zip_codes: values.restricted_zip_codes || null,
      voter_redaction_enabled: values.voter_redaction_enabled ?? false,
    },
  };
}

export const formSchema = toTypedSchema(
  z.object(schemaObject).superRefine((data, ctx) => addVoiceRecordingIssues(data, ctx, { isDraft: false }))
);
