import * as z from 'zod';

export const canvassingAppProjectCreateSchema = z.object({
  name: z
    .string({ message: 'Project Name is required' })
    .trim()
    .min(1, { message: 'Project Name is required' })
    .max(255, { message: 'Project Name cannot exceed 255 characters' }),
  id: z
    .string({ message: 'Project ID is required' })
    .trim()
    .min(1, { message: 'Project ID is required' })
    .max(100, { message: 'Project ID cannot exceed 100 characters' }),
});

export type CanvassingAppProjectCreateInput = z.input<typeof canvassingAppProjectCreateSchema>;
export type CanvassingAppProjectCreateOutput = z.output<typeof canvassingAppProjectCreateSchema>;
