import { isEqual } from 'lodash';
import { getDeletedContractTemplates, parseContractConfigs } from '~/utils/contractConfigs';
import type { CanvassingProjectConfiguration, SignatureProjectConfiguration } from '~/types/projects/configuration';

export type SectionState = 'complete' | 'disabled' | 'needs-setup' | 'edited' | 'edited-invalid';

export const CANVASSING_SECTION_IDS = ['staffing', 'contracts', 'payment', 'voice', 'app', 'goal', 'budget'] as const;
export type CanvassingSectionId = (typeof CANVASSING_SECTION_IDS)[number];

export const SIGNATURE_SECTION_IDS = ['staffing', 'contracts', 'payment', 'voice', 'budget'] as const;
export type SignatureSectionId = (typeof SIGNATURE_SECTION_IDS)[number];

// Maps form field name → owning section. Used by the form components to mark a
// section as invalid when one of its fields fails validation. Kept here (next
// to the section IDs) so a new section can't be added without also wiring up
// the fields that belong to it.
export const CANVASSING_FIELD_TO_SECTION = {
  audio_recording: 'voice',
  restricted_zip_codes: 'voice',
  voter_redaction_enabled: 'voice',
  canvassing_application_name: 'app',
  canvassing_application_ids: 'app',
  survey_goal_percentage: 'goal',
  staffing_goal: 'staffing',
  staffing_status: 'staffing',
  contract_template_local: 'contracts',
  contract_template_quick_response_force: 'contracts',
  use_separate_qrf_template: 'contracts',
  contract_sending_enabled: 'contracts',
  payments_enabled: 'payment',
  for_canvasser_per_hour: 'payment',
  qrf_for_canvasser_per_hour: 'payment',
  earning_review_hours: 'payment',
  allowed_break_minutes_per_hour: 'payment',
  grace_allowance_minutes: 'payment',
  walk_speed_mph: 'payment',
  drive_speed_mph: 'payment',
  increased_pay_rate_enabled: 'payment',
  increased_for_canvasser_per_hour: 'payment',
  increased_qrf_for_canvasser_per_hour: 'payment',
  increased_pay_rate_threshold_in_hours: 'payment',
  budget_contract: 'budget',
  budget_received: 'budget',
} as const satisfies Record<string, CanvassingSectionId>;

// Maps a form field → master toggles it depends on. When any listed toggle is
// off/falsy, the field is "gated off" — its validation errors are ignored when
// computing section invalidity, since the field is hidden from the user.
// Canvassing has no voice gate because the canvassing voice section uses
// `audio_recording` (an enum), not a boolean toggle.
export const CANVASSING_FIELD_GATES = {
  for_canvasser_per_hour: ['payments_enabled'],
  qrf_for_canvasser_per_hour: ['payments_enabled'],
  increased_for_canvasser_per_hour: ['payments_enabled', 'increased_pay_rate_enabled'],
  increased_qrf_for_canvasser_per_hour: ['payments_enabled', 'increased_pay_rate_enabled'],
  increased_pay_rate_threshold_in_hours: ['payments_enabled', 'increased_pay_rate_enabled'],
  contract_template_local: ['contract_sending_enabled'],
  contract_template_quick_response_force: ['contract_sending_enabled'],
} as const satisfies Record<string, readonly string[]>;

export const SIGNATURE_FIELD_TO_SECTION = {
  voice_verification_enabled: 'voice',
  audio_saving_enabled: 'voice',
  audio_expiration_days: 'voice',
  staffing_goal: 'staffing',
  staffing_status: 'staffing',
  contract_template_local: 'contracts',
  contract_template_quick_response_force: 'contracts',
  use_separate_qrf_template: 'contracts',
  contract_sending_enabled: 'contracts',
  payments_enabled: 'payment',
  for_canvasser_per_signature: 'payment',
  for_client_per_signature: 'payment',
  qrf_for_canvasser_per_signature: 'payment',
  earning_review_hours: 'payment',
  budget_contract: 'budget',
  budget_received: 'budget',
} as const satisfies Record<string, SignatureSectionId>;

export const SIGNATURE_FIELD_GATES = {
  for_canvasser_per_signature: ['payments_enabled'],
  for_client_per_signature: ['payments_enabled'],
  qrf_for_canvasser_per_signature: ['payments_enabled'],
  audio_saving_enabled: ['voice_verification_enabled'],
  audio_expiration_days: ['voice_verification_enabled'],
  contract_template_local: ['contract_sending_enabled'],
  contract_template_quick_response_force: ['contract_sending_enabled'],
} as const satisfies Record<string, readonly string[]>;

export function isFieldGatedOff(
  values: Record<string, unknown>,
  fieldName: string,
  gates: Record<string, readonly string[]>
): boolean {
  const fieldGates = gates[fieldName];
  if (!fieldGates) return false;
  return fieldGates.some((gate) => !values[gate]);
}

interface StateInput<T, SectionId extends string> {
  saved: T;
  working: T;
  invalidSections: Set<SectionId>;
  disabledSections?: Set<SectionId>;
}

// -------- canvassing --------

export function getCanvassingSectionStates(
  input: StateInput<CanvassingProjectConfiguration, CanvassingSectionId>
): Record<CanvassingSectionId, SectionState> {
  const { saved, working, invalidSections, disabledSections } = input;

  function needsSetup(id: CanvassingSectionId): boolean {
    switch (id) {
      case 'voice':
        return saved.audio_recording == null;
      case 'app':
        return saved.canvassing_application_name == null || saved.canvassing_application_ids == null;
      case 'goal':
        return saved.survey_goal_percentage == null;
      case 'staffing':
        return saved.staffing.goal == null;
      case 'contracts':
        return !!saved.contract_sending_enabled && getDeletedContractTemplates(saved.contract_configs).length > 0;
      case 'payment':
        return (
          saved.pricing.payments_enabled === true &&
          (saved.pricing.for_canvasser_per_hour == null || saved.pricing.qrf_for_canvasser_per_hour == null)
        );
      case 'budget':
        return saved.budget.contract == null || saved.budget.received == null;
    }
  }

  function sliceOf(id: CanvassingSectionId, c: CanvassingProjectConfiguration): unknown {
    switch (id) {
      case 'voice':
        return {
          audio_recording: c.audio_recording,
          restricted_zip_codes: c.restricted_zip_codes,
          voter_redaction_enabled: c.voter_redaction_enabled,
        };
      case 'app':
        return {
          canvassing_application_name: c.canvassing_application_name,
          canvassing_application_ids: c.canvassing_application_ids,
        };
      case 'goal':
        return { survey_goal_percentage: c.survey_goal_percentage };
      case 'staffing':
        return c.staffing;
      case 'contracts': {
        if (!c.contract_sending_enabled) return { contract_sending_enabled: false };
        // Raw contract_configs has shape mismatch between read (template_provider_id)
        // and write (template_id) APIs, so compare the parsed view.
        const { contractTemplateLocal, contractTemplateQrf, useSeparateQrf } = parseContractConfigs(c.contract_configs);
        return {
          contract_template_local: contractTemplateLocal,
          contract_template_quick_response_force: contractTemplateQrf,
          use_separate_qrf_template: useSeparateQrf,
          contract_sending_enabled: true,
        };
      }
      case 'payment':
        if (!c.pricing.payments_enabled) {
          return {
            payments_enabled: false,
            earning_review_hours: c.pricing.earning_review_hours,
            allowed_break_minutes_per_hour: c.pricing.allowed_break_minutes_per_hour,
            grace_allowance_minutes: c.pricing.grace_allowance_minutes,
          };
        }
        return c.pricing;
      case 'budget':
        return c.budget;
    }
  }

  const result = {} as Record<CanvassingSectionId, SectionState>;
  for (const id of CANVASSING_SECTION_IDS) {
    const edited = !isEqual(sliceOf(id, saved), sliceOf(id, working));
    const invalid = invalidSections.has(id);
    if (edited && invalid) result[id] = 'edited-invalid';
    else if (edited) result[id] = 'edited';
    else if (disabledSections?.has(id)) result[id] = 'disabled';
    else if (invalid || needsSetup(id)) result[id] = 'needs-setup';
    else result[id] = 'complete';
  }
  return result;
}

// -------- signature --------

export function getSignatureSectionStates(
  input: StateInput<SignatureProjectConfiguration, SignatureSectionId>
): Record<SignatureSectionId, SectionState> {
  const { saved, working, invalidSections, disabledSections } = input;

  function needsSetup(id: SignatureSectionId): boolean {
    switch (id) {
      case 'voice':
        return saved.voice_verification_enabled === null;
      case 'staffing':
        return saved.staffing.goal == null;
      case 'contracts':
        return !!saved.contract_sending_enabled && getDeletedContractTemplates(saved.contract_configs).length > 0;
      case 'payment':
        return (
          saved.pricing.payments_enabled === true &&
          (saved.pricing.for_canvasser_per_signature == null || saved.pricing.for_client_per_signature == null)
        );
      case 'budget':
        return saved.budget.contract == null || saved.budget.received == null;
    }
  }

  function sliceOf(id: SignatureSectionId, c: SignatureProjectConfiguration): unknown {
    switch (id) {
      case 'voice':
        if (c.voice_verification_enabled === false) {
          return { voice_verification_enabled: false };
        }
        return {
          voice_verification_enabled: c.voice_verification_enabled,
          audio_saving_enabled: c.audio_saving_enabled,
          audio_expiration_days: c.audio_expiration_days,
        };
      case 'staffing':
        return c.staffing;
      case 'contracts': {
        if (!c.contract_sending_enabled) return { contract_sending_enabled: false };
        const { contractTemplateLocal, contractTemplateQrf, useSeparateQrf } = parseContractConfigs(c.contract_configs);
        return {
          contract_template_local: contractTemplateLocal,
          contract_template_quick_response_force: contractTemplateQrf,
          use_separate_qrf_template: useSeparateQrf,
          contract_sending_enabled: true,
        };
      }
      case 'payment':
        if (!c.pricing.payments_enabled) {
          return { payments_enabled: false, earning_review_hours: c.pricing.earning_review_hours };
        }
        return c.pricing;
      case 'budget':
        return c.budget;
    }
  }

  const result = {} as Record<SignatureSectionId, SectionState>;
  for (const id of SIGNATURE_SECTION_IDS) {
    const edited = !isEqual(sliceOf(id, saved), sliceOf(id, working));
    const invalid = invalidSections.has(id);
    if (edited && invalid) result[id] = 'edited-invalid';
    else if (edited) result[id] = 'edited';
    else if (disabledSections?.has(id)) result[id] = 'disabled';
    else if (invalid || needsSetup(id)) result[id] = 'needs-setup';
    else result[id] = 'complete';
  }
  return result;
}
