import type { EditProjectConfigRequest } from '~/client';
import type { ContractConfigs } from '~/types/projects/configuration';

export function buildContractConfigs(
  localId: string | undefined,
  qrfId: string | undefined,
  useSeparateQrf: boolean
): EditProjectConfigRequest['contract_configs'] {
  const configs: EditProjectConfigRequest['contract_configs'] = {};
  if (!localId) return configs;
  configs.local = { template_id: localId };
  const effectiveQrfId = useSeparateQrf ? qrfId : localId;
  if (effectiveQrfId) configs.quick_response_force = { template_id: effectiveQrfId };
  return configs;
}

interface ContractConfigsSubmitValues {
  contract_sending_enabled?: boolean | null;
  contract_template_local?: string | null;
  contract_template_quick_response_force?: string | null;
  use_separate_qrf_template?: boolean | null;
}

export function buildContractConfigsForSubmit(
  values: ContractConfigsSubmitValues
): EditProjectConfigRequest['contract_configs'] {
  if (!values.contract_sending_enabled) return {};
  return buildContractConfigs(
    values.contract_template_local ?? undefined,
    values.contract_template_quick_response_force ?? undefined,
    !!values.use_separate_qrf_template
  );
}

// Saved contract templates that the provider (e.g. SignWell) has since deleted.
// Deleted templates are excluded from the selector dropdown, so callers use this
// to flag the orphaned selection and keep its name visible.
export function getDeletedContractTemplates(configs: ContractConfigs | undefined): { id: string; name: string }[] {
  if (!configs) return [];
  const byId = new Map<string, { id: string; name: string }>();
  for (const cfg of Object.values(configs)) {
    if (!cfg || !cfg.deleted) continue;
    if (!byId.has(cfg.template_provider_id)) {
      byId.set(cfg.template_provider_id, { id: cfg.template_provider_id, name: cfg.template_name });
    }
  }
  return [...byId.values()];
}

export function parseContractConfigs(configs: ContractConfigs | undefined) {
  // Tolerant of both API shapes: read responses use `template_provider_id`,
  // write requests built via buildContractConfigs use `template_id`.
  const readId = (cfg: { template_provider_id?: string | null; template_id?: string | null } | null | undefined) =>
    cfg?.template_provider_id ?? cfg?.template_id ?? null;
  const savedLocalId = readId(configs?.local);
  const savedQrfId = readId(configs?.quick_response_force);
  const useSeparateQrf = !!(savedLocalId && savedQrfId && savedLocalId !== savedQrfId);
  return {
    savedLocalId,
    savedQrfId,
    useSeparateQrf,
    contractTemplateLocal: savedLocalId || savedQrfId || null,
    contractTemplateQrf: useSeparateQrf ? savedQrfId : null,
  };
}
