import { editProjectConfig } from '~/client';
import type { EditProjectConfigResponse, EditProjectConfigRequest } from '~/client';
import { showToastError, showToastSuccess } from '~/utils/show-toast';

export const useEditProjectConfiguration = defineMutation(() => {
  const { mutateAsync, asyncStatus } = useMutation({
    mutation: (params: { data: EditProjectConfigRequest; projectId: string }): Promise<EditProjectConfigResponse> =>
      editProjectConfig({
        composable: '$fetch',
        path: { project_id: params.projectId },
        body: ref(params.data),
      }),
    onSuccess: (_, params) => {
      const queryCache = useQueryCache();
      queryCache.invalidateQueries({ key: ['project-configuration', params.projectId] });
      queryCache.invalidateQueries({ key: ['project-edit-tabs-status', params.projectId] });
      showToastSuccess(`Project configuration edited successfully`);
    },
    onError(error) {
      showToastError(error || 'Failed to save configuration');
    },
  });

  return {
    editProjectConfiguration: mutateAsync,
    isEditProjectConfigurationLoading: computed(() => asyncStatus.value === 'loading'),
  };
});
