<template>
  <ProjectEditConfigurationFieldRow label="Canvassing App" description="Which canvassing platform powers this project.">
    <FormItemWrapper name="canvassing_application_name" slot-wrapper-class="sm:items-end">
      <template #default="{ slots }">
        <KitFormsSelect
          id="canvassing_application_name"
          :items="canvassingAppsProcessed"
          :component-field="slots.componentField"
          :loading="isLoadingCanvassingApps"
          :error="canvassingAppsError ? canvassingAppsError?.data?.detail || 'Failed to load canvassing apps' : ''"
          trigger-class="w-full sm:w-72"
          @update:model-value="onCanvassingAppChange"
        />
      </template>
    </FormItemWrapper>
  </ProjectEditConfigurationFieldRow>

  <ProjectEditConfigurationFieldRow
    v-if="isNuminar"
    label="Numinar Sync Source"
    description="New syncs Numinar data from S3 (recommended). Old uses the legacy Numinar API."
  >
    <FormItemWrapper name="numinar_source" slot-wrapper-class="sm:items-end">
      <template #default="{ slots }">
        <KitFormsSelect
          id="numinar_source"
          :items="numinarSourceOptions"
          :component-field="slots.componentField"
          :disabled="!isDraft"
          trigger-class="w-full sm:w-72"
          @update:model-value="onNuminarSourceChange"
        />
      </template>
    </FormItemWrapper>
  </ProjectEditConfigurationFieldRow>

  <ProjectEditConfigurationFieldRow
    v-if="isNuminarS3"
    label="Numinar Prefix"
    description="Which Numinar S3 export folder (org) this project reads from."
  >
    <div class="flex w-full flex-col gap-1.5 sm:w-72 sm:items-end">
      <FormItemWrapper name="numinar_file_prefix" slot-wrapper-class="sm:items-end">
        <template #default="{ slots }">
          <KitFormsSelect
            id="numinar_file_prefix"
            :items="numinarPrefixListProcessed"
            :component-field="slots.componentField"
            :loading="isLoadingNuminarPrefixes"
            :disabled="!isDraft"
            :error="numinarPrefixesError ? numinarPrefixesError?.data?.detail || 'Failed to load prefixes' : ''"
            trigger-class="w-full sm:w-72"
          />
        </template>
      </FormItemWrapper>
      <span v-if="!isDraft" class="text-xs text-muted-foreground sm:text-right">
        Editable only when project is in <b>Draft</b> state.
      </span>
    </div>
  </ProjectEditConfigurationFieldRow>

  <ProjectEditConfigurationFieldRow
    v-if="isI360"
    label="i360 File Prefix"
    description="Which i360 export file set this project reads from."
  >
    <div class="flex w-full flex-col gap-1.5 sm:w-72 sm:items-end">
      <FormItemWrapper name="i360_file_prefix" slot-wrapper-class="sm:items-end">
        <template #default="{ slots }">
          <KitFormsSelect
            id="i360_file_prefix"
            :items="prefixListProcessed"
            :component-field="slots.componentField"
            :loading="isLoadingPrefixes"
            :disabled="!isDraft"
            :error="prefixesError ? prefixesError?.data?.detail || 'Failed to load prefixes' : ''"
            trigger-class="w-full sm:w-72"
            @update:model-value="onPrefixChange"
          />
        </template>
      </FormItemWrapper>
      <span v-if="!isDraft" class="text-xs text-muted-foreground sm:text-right">
        Editable only when project is in <b>Draft</b> state.
      </span>
    </div>
  </ProjectEditConfigurationFieldRow>

  <ProjectEditConfigurationFieldRow
    v-if="isPulsar"
    label="Pulsar API Key"
    description="API key used to connect to the Pulsar API."
  >
    <div class="flex w-full flex-col gap-1.5 sm:w-72 sm:items-end">
      <template v-if="isDraft">
        <template v-if="showPulsarKeyInput">
          <FormItemWrapper name="pulsar_api_key" slot-wrapper-class="sm:items-end">
            <template #default="{ slots }">
              <KitFormPasswordInput
                id="pulsar_api_key"
                class="w-full sm:w-72"
                placeholder="Enter API key"
                :component-field="slots.componentField"
                autocomplete="off"
              />
            </template>
          </FormItemWrapper>
          <Button
            v-if="apiKeySet"
            type="button"
            variant="link"
            class="h-auto self-start p-0 sm:self-end"
            data-testid="pulsar-cancel-rewrite-button"
            @click="cancelPulsarRewrite"
          >
            Cancel
          </Button>
        </template>
        <div v-else class="flex w-full items-center gap-2 sm:w-72">
          <Input :model-value="maskedPulsarKey" disabled class="min-w-0 flex-1 font-mono" />
          <Button
            type="button"
            variant="outline"
            class="aspect-square h-10 shrink-0"
            :prepend-icon="PencilIcon"
            aria-label="Rewrite API key"
            data-testid="pulsar-rewrite-key-button"
            @click="startPulsarRewrite"
          />
        </div>
      </template>
      <template v-else>
        <Input v-if="apiKeySet" :model-value="maskedPulsarKey" disabled class="w-full font-mono sm:w-72" />
        <span class="text-xs text-muted-foreground sm:text-right">
          Editable only when project is in <b>Draft</b> state.
        </span>
      </template>
    </div>
  </ProjectEditConfigurationFieldRow>

  <ProjectEditConfigurationFieldRow
    v-if="!isPulsar && !isNuminarS3"
    label="Project In Canvassing App"
    description="One or more projects in the connected canvassing app."
  >
    <div class="flex flex-col gap-1.5">
      <FormItemWrapper name="canvassing_application_ids">
        <template #default="{ slots }">
          <KitFormsComboboxMultiple
            id="canvassing_application_ids"
            placeholder="Select project"
            :items="surveyListProcessed"
            :component-field="slots.componentField"
            :loading="isLoadingSurveys"
            :disabled="isSurveyDisabled"
            :null-is-all="false"
            :error="surveysError ? surveysError?.data?.detail || 'Failed to load canvassing projects' : ''"
            empty-text="No projects found"
            element-width="w-full sm:w-72"
          />
        </template>
      </FormItemWrapper>
      <CanvassingAppProjectCreateDialog
        v-if="selectedCanvassingApp"
        :app-name="selectedCanvassingApp"
        @created="onProjectCreated"
      >
        <Button
          type="button"
          variant="link"
          class="h-auto gap-1 self-start p-0"
          data-testid="canvassing-app-create-project-button"
        >
          <Plus />
          Add New Entry
        </Button>
      </CanvassingAppProjectCreateDialog>
    </div>
  </ProjectEditConfigurationFieldRow>

  <ProjectEditConfigurationFieldRow
    v-if="selectedCanvassingApp"
    label="Users In Canvassing App"
    description="Canvassers connected to this project in the canvassing app."
  >
    <div class="flex w-full flex-col gap-1.5 sm:w-72 sm:items-end">
      <CanvassingAppUsersModal
        :project-id="projectId"
        :can-manage-users="hasSavedCanvassingApp"
        :app-name="selectedCanvassingApp"
        :app-ids="pickedAppIds"
      >
        <Button
          type="button"
          variant="outline"
          :disabled="!hasPickedCanvassingApp"
          data-testid="canvassing-app-users-preview-button"
        >
          Preview
        </Button>
      </CanvassingAppUsersModal>
      <span v-if="previewHint" class="text-xs text-muted-foreground sm:text-right">
        {{ previewHint }}
      </span>
    </div>
  </ProjectEditConfigurationFieldRow>
</template>

<script setup lang="ts">
import { Plus, PencilIcon } from 'lucide-vue-next';
import { useField, useFormContext } from 'vee-validate';
import { useSelectorCanvassingAppList } from '~/queries/selectors/canvassingApps';
import { useSelectorI360PrefixList, useSelectorCanvassingPrefixList } from '~/queries/selectors/canvassingPrefixes';
import {
  I360_DEFAULT_PREFIX_SENTINEL,
  prefixToSelectValue,
  selectValueToPrefix,
} from '~/constants/validationSchemas/projectCanvassingApp';
import { getSelectorSurveyList } from '~/client';
import type { AcceptableValue } from 'reka-ui';
import type {
  CanvassingApplicationName,
  GetSelectorSurveyListResponse,
  NuminarSyncSource,
  SurveySelectorItem,
} from '~/client';
import type { CanvassingApplicationConfig } from '~/types/projects/configuration';

interface Props {
  isDraft: boolean;
  config: CanvassingApplicationConfig;
  projectId: string;
}

const props = defineProps<Props>();

// The saved config carries whether a Pulsar key exists plus the last-4 preview; the key itself is
// write-only and never sent in full.
const apiKeySet = computed(() => props.config?.name === 'pulsar' && props.config.api_key_set);
const apiKeyLast4 = computed(() => (props.config?.name === 'pulsar' ? props.config.api_key_last4 : null));
const maskedPulsarKey = computed(() => (apiKeyLast4.value ? `••••${apiKeyLast4.value}` : '••••••••'));

const { values, setFieldValue } = useFormContext();

const {
  canvassingApps,
  isLoading: isLoadingCanvassingApps,
  error: canvassingAppsError,
} = useSelectorCanvassingAppList();

const { value: canvassingApplicationNameField } = useField<CanvassingApplicationName | '' | undefined>(
  'canvassing_application_name'
);
const { value: i360FilePrefixField } = useField<string | undefined>('i360_file_prefix');
const { value: pulsarApiKeyField } = useField<string | undefined>('pulsar_api_key');
const { value: numinarSourceField } = useField<NuminarSyncSource | undefined>('numinar_source');
const { value: numinarFilePrefixField } = useField<string | undefined>('numinar_file_prefix');

const isI360 = computed(() => canvassingApplicationNameField.value === 'i360');
const isPulsar = computed(() => canvassingApplicationNameField.value === 'pulsar');
const isNuminar = computed(() => canvassingApplicationNameField.value === 'numinar');
// New = S3 pipeline (default). Old = legacy Numinar API.
const isNuminarS3 = computed(() => isNuminar.value && numinarSourceField.value === 's3');

const numinarSourceOptions: SelectItem<NuminarSyncSource>[] = [
  { value: 's3', name: 'New (S3)' },
  { value: 'api', name: 'Old (API)' },
];

// The Select's componentField writes numinar_source itself; here we only clear the mode-specific
// selections so a stale prefix/project pick doesn't leak across a mode switch.
function onNuminarSourceChange() {
  setFieldValue('numinar_file_prefix', undefined, false);
  setFieldValue('canvassing_application_ids', undefined, false);
}

// When a key already exists, keep the input hidden behind a "Rewrite existing key" button so it
// can't be overwritten by accident. Entering the rewrite flow sets the field to '' (input shown,
// but still no pending change until the admin types); cancelling / saving resets it to undefined.
const showPulsarKeyInput = computed(() => !apiKeySet.value || pulsarApiKeyField.value !== undefined);

function startPulsarRewrite() {
  setFieldValue('pulsar_api_key', '');
}

function cancelPulsarRewrite() {
  setFieldValue('pulsar_api_key', undefined, false);
}

const { prefixes, isLoading: isLoadingPrefixes, error: prefixesError } = useSelectorI360PrefixList(isI360);

const {
  prefixes: numinarPrefixes,
  isLoading: isLoadingNuminarPrefixes,
  error: numinarPrefixesError,
} = useSelectorCanvassingPrefixList('numinar', isNuminarS3);

// For i360 the orgs depend on the chosen prefix, so wait for one before loading surveys.
const isSurveyDisabled = computed(
  () => !canvassingApplicationNameField.value || (isI360.value && i360FilePrefixField.value === undefined)
);

const {
  data: surveyData,
  isLoading: isLoadingSurveys,
  error: surveysError,
} = useQuery({
  key: () => ['selector-surveys-list', canvassingApplicationNameField.value ?? '', i360FilePrefixField.value ?? ''],
  query: (): Promise<GetSelectorSurveyListResponse> =>
    getSelectorSurveyList({
      composable: '$fetch',
      query: canvassingApplicationNameField.value
        ? {
            app_name: canvassingApplicationNameField.value,
            ...(isI360.value && i360FilePrefixField.value !== undefined
              ? { prefix: selectValueToPrefix(i360FilePrefixField.value) }
              : {}),
          }
        : {},
    }),
  enabled: () =>
    !!canvassingApplicationNameField.value &&
    !isPulsar.value &&
    !isNuminarS3.value &&
    (!isI360.value || i360FilePrefixField.value !== undefined),
  staleTime: 0,
});

function onCanvassingAppChange(value: AcceptableValue) {
  setFieldValue('canvassing_application_ids', undefined, false);
  setFieldValue('pulsar_api_key', undefined, false);
  // i360 is the only app with a file-prefix selector — pre-fill it with the default ("No Prefix")
  // sentinel so the selector isn't left empty. Other apps have no prefix concept.
  setFieldValue('i360_file_prefix', value === 'i360' ? I360_DEFAULT_PREFIX_SENTINEL : undefined, false);
  // Numinar defaults to the new S3 pipeline; the prefix must be picked from the discovered list
  // (there is no valid empty/default prefix for Numinar S3), so leave it unset.
  setFieldValue('numinar_source', value === 'numinar' ? 's3' : undefined, false);
  setFieldValue('numinar_file_prefix', undefined, false);
}

function onPrefixChange() {
  setFieldValue('canvassing_application_ids', undefined, false);
}

const prefixListProcessed = computed<SelectItem<string>[]>(() =>
  prefixes.value.map((item) => ({ value: prefixToSelectValue(item.prefix), name: item.prefix || 'No Prefix' }))
);

// Numinar S3 has no "default"/empty bucket-root prefix — every project maps to a real org folder.
const numinarPrefixListProcessed = computed<SelectItem<string>[]>(() =>
  numinarPrefixes.value
    .filter((item) => item.prefix !== '')
    .map((item) => ({ value: prefixToSelectValue(item.prefix), name: item.prefix }))
);

const canvassingAppsProcessed = computed<SelectItem<CanvassingApplicationName>[]>(() => {
  if (canvassingApps.value) {
    return canvassingApps.value.map((app) => ({
      value: app.value as CanvassingApplicationName,
      name: app.name,
    }));
  } else return [];
});

const surveyListProcessed = computed<SelectItem<Record<string, string[]>>[]>(() =>
  (surveyData.value?.items ?? []).map((survey) => ({
    value: survey.app_id,
    name: survey.name,
  }))
);

// Non-empty selected app, narrowed for the create-project dialog prop.
const selectedCanvassingApp = computed<CanvassingApplicationName | undefined>(
  () => canvassingApplicationNameField.value || undefined
);

// The users preview reads persisted data, so it is gated on the SAVED config — matching
// the "available after saving" hint below the button. For Pulsar (no org selection) a
// saved API key is the equivalent of a configured canvassing app.
const hasSavedCanvassingApp = computed(() => {
  if (!props.config) return false;
  if (props.config.name === 'pulsar') return props.config.api_key_set;
  return (props.config.org_ids?.length ?? 0) > 0;
});

// Flattened org ids currently selected in the form. Passed to the preview so a picked-but-unsaved
// project still lists its users (the endpoint falls back to the saved config when this is empty).
const pickedAppIds = computed<string[]>(() => {
  const ids = values.canvassing_application_ids as Array<Record<string, string[]>> | undefined;
  return ids?.flatMap((item) => item['org-id'] ?? []) ?? [];
});

// A project is "picked" as soon as the admin makes a draft selection, before saving. Preview is
// enabled at this point so the currently-linked users can be inspected; adding/importing stays
// gated on the saved config (passed as `can-manage-users`). Pulsar has no project picker, so
// there picked == saved.
const hasPickedCanvassingApp = computed(() => {
  if (isPulsar.value) return hasSavedCanvassingApp.value;
  return pickedAppIds.value.length > 0;
});

// Only the "can't preview yet" case is hinted here. Once a project is picked the preview opens, and
// the "save to add or import" note lives inside the modal next to the disabled actions.
const previewHint = computed(() => {
  if (hasPickedCanvassingApp.value) return '';
  return isPulsar.value
    ? 'Preview is available after the canvassing app configuration is saved.'
    : 'Select a project in the canvassing app to preview its users.';
});

function onProjectCreated(item: SurveySelectorItem) {
  const current = (values.canvassing_application_ids as Array<Record<string, string[]>> | undefined) ?? [];
  setFieldValue('canvassing_application_ids', [...current, item.app_id]);
}
</script>
