<template>
  <Dialog v-model:open="isOpen" @update:open="onOpenChange">
    <DialogTrigger as-child>
      <slot />
    </DialogTrigger>
    <DialogContent class="gap-4 max-w-xs sm:max-w-sm md:max-w-5xl">
      <DialogHeader>
        <DialogTitle>Users In Canvassing App</DialogTitle>
        <DialogDescription>
          Canvassers connected to this project in the canvassing app and the platform user each relates to.
        </DialogDescription>
      </DialogHeader>

      <template v-if="view === 'table'">
        <div class="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
          <div class="relative w-full sm:max-w-xs">
            <Input v-model="search" class="pl-10 shadow-sm" placeholder="Search app users..." />
            <span class="absolute start-0 inset-y-0 flex items-center justify-center px-4">
              <Search :class="['size-4', !search && 'text-muted-foreground']" />
            </span>
            <XIcon
              v-if="search.length > 0"
              class="absolute right-4 top-[0.75rem] ml-2 h-4 w-4 shrink-0 cursor-pointer"
              @click.stop.prevent="search = ''"
            />
          </div>
          <div class="flex flex-col gap-1.5 sm:items-end">
            <div class="flex gap-2">
              <CanvassingAppCanvasserCreateDialog :project-id="projectId" @created="() => refetchUsers()">
                <Button
                  type="button"
                  :prepend-icon="UserPlusIcon"
                  :disabled="!canManageUsers"
                  :title="canManageUsers ? undefined : 'Save the configuration to add users'"
                >
                  Add Canvasser
                </Button>
              </CanvassingAppCanvasserCreateDialog>
              <Button
                type="button"
                variant="outline"
                :prepend-icon="FileUpIcon"
                :disabled="hasActiveImport || !canManageUsers"
                :title="importButtonTitle"
                data-testid="canvassing-app-users-open-import"
                @click="view = 'upload'"
              >
                Import CSV
              </Button>
            </div>
            <p v-if="!canManageUsers" class="text-sm text-muted-foreground sm:text-right">
              Save the configuration to add or import users.
            </p>
          </div>
        </div>

        <div>
          <AppLoader v-if="isInitialUsersLoad" variant="inline" subject="app users" />
          <AppError
            v-else-if="usersError"
            title="Failed to load app users"
            :error="usersError"
            variant="table"
            :action="refetchUsers"
            action-text="Retry"
          />
          <template v-else>
            <!-- Header and footer live outside the scroll area so the scrollbar spans only
                 the rows. The two tables share table-fixed (equal thirds) to keep columns
                 aligned. -->
            <Table class="hidden md:table md:table-fixed rounded-t-lg overflow-clip">
              <ResponsiveTableHeader>
                <ResponsiveTableHead>Name</ResponsiveTableHead>
                <ResponsiveTableHead>Username/Email</ResponsiveTableHead>
                <ResponsiveTableHead>Related User</ResponsiveTableHead>
              </ResponsiveTableHeader>
            </Table>
            <div class="max-h-[55vh] overflow-y-auto">
              <Table class="flex flex-col sm:table md:table-fixed">
                <ResponsiveTableBody>
                  <ResponsiveTableEmpty
                    v-if="items.length === 0"
                    :colspan="3"
                    :cols="3"
                    :cols-sm="3"
                    cell-class="text-center"
                  >
                    <AppEmpty subject="app users" variant="table" />
                  </ResponsiveTableEmpty>
                  <ResponsiveTableRow v-for="(item, index) in items" v-else :key="`${item.email}-${index}`">
                    <ResponsiveTableCell :cols="3" :cols-sm="3" label="Name">
                      <div class="flex items-center gap-2">
                        <span v-if="canvasserName(item.first_name, item.last_name)" class="font-medium">{{
                          canvasserName(item.first_name, item.last_name)
                        }}</span>
                        <span v-else class="text-muted-foreground">Unknown</span>
                        <Badge v-if="item.is_manual" variant="info" size="sm">Manual</Badge>
                      </div>
                    </ResponsiveTableCell>
                    <ResponsiveTableCell :cols="3" :cols-sm="3" label="Username/Email">{{
                      item.email
                    }}</ResponsiveTableCell>
                    <ResponsiveTableCell :cols="3" :cols-sm="3" label="Related User">
                      <div v-if="item.related_user" class="flex flex-col">
                        <NuxtLink
                          :to="{ name: 'users-id', params: { id: item.related_user.id } }"
                          class="font-medium underline underline-offset-2"
                        >
                          {{ item.related_user.first_name }} {{ item.related_user.last_name }}
                        </NuxtLink>
                        <span class="text-sm text-muted-foreground">{{ item.related_user.email }}</span>
                      </div>
                      <Badge v-else variant="default" size="sm" class="text-muted-foreground">Not linked</Badge>
                    </ResponsiveTableCell>
                  </ResponsiveTableRow>
                </ResponsiveTableBody>
              </Table>
            </div>
            <div v-if="totalCount > 0" class="border-t p-4">
              <AppPagination
                controlled
                :page="page"
                :size="size"
                :total="totalCount"
                label="app users"
                @update:page="(value) => (page = value)"
              />
            </div>
          </template>
        </div>
      </template>

      <template v-else-if="view === 'upload'">
        <p class="text-sm text-muted-foreground">
          Upload a CSV with first name, last name and email/username columns. Column names are detected automatically.
          Duplicates and rows missing a required value are skipped.
        </p>
        <KitFormFileUpload
          form-id="canvassing-app-users-modal-import-file"
          :file-types="['.csv']"
          :file-size-limit="50"
          size-unit="MB"
          @on-process-data="onFileUploaded"
        />
        <div class="flex justify-end gap-2">
          <Button type="button" variant="outline" @click="backToTable">Cancel</Button>
          <Button type="button" :disabled="!s3Url || isSubmitting" :loading="isSubmitting" @click="submitImport">
            Import
          </Button>
        </div>
      </template>

      <template v-else>
        <div class="max-h-[60vh] overflow-y-auto flex flex-col gap-4">
          <State
            v-if="importStatus === 'PENDING' || importStatus === 'PROCESSING'"
            :title="importStatus === 'PENDING' ? 'Pending' : 'Processing'"
            :description="
              importStatus === 'PENDING'
                ? 'Import is queued and will start shortly.'
                : 'Importing canvassing app users from CSV. This may take a moment.'
            "
            :icon="Spinner"
            icon-class="size-16 w-16"
          />
          <State
            v-else-if="importStatus === 'SUCCESS'"
            title="Import Complete"
            description="Canvassing app users have been imported successfully."
            :icon="CircleCheckIcon"
            icon-class="size-16 w-16 text-green-600"
          />
          <template v-else-if="importStatus === 'FAILED'">
            <State
              title="Import Failed"
              :md-description="importError?.title || 'An error occurred while importing the file.'"
              :icon="CircleXIcon"
              icon-class="size-16 w-16 text-destructive"
            />
            <AppMarkdown
              v-if="importError?.details"
              :markdown="importError.details"
              class="text-sm text-muted-foreground"
            />
          </template>

          <div v-if="isImportFinished && hasCounts" class="grid grid-cols-2 sm:grid-cols-4 gap-3 text-sm">
            <Card class="shadow-none">
              <CardContent class="flex flex-col items-center gap-1 p-4">
                <span class="text-2xl font-semibold">{{ latestImport?.all_rows_count ?? 0 }}</span>
                <span class="text-xs text-muted-foreground">Total rows</span>
              </CardContent>
            </Card>
            <Card class="shadow-none">
              <CardContent class="flex flex-col items-center gap-1 p-4">
                <span class="text-2xl font-semibold text-green-600">{{ latestImport?.inserted_rows_count ?? 0 }}</span>
                <span class="text-xs text-muted-foreground">Created</span>
              </CardContent>
            </Card>
            <Card class="shadow-none">
              <CardContent class="flex flex-col items-center gap-1 p-4">
                <span class="text-2xl font-semibold text-destructive">{{ latestImport?.failed_rows_count ?? 0 }}</span>
                <span class="text-xs text-muted-foreground">Failed</span>
              </CardContent>
            </Card>
            <Card class="shadow-none">
              <CardContent class="flex flex-col items-center gap-1 p-4">
                <span class="text-2xl font-semibold text-orange-500">{{ latestImport?.filtered_rows_count ?? 0 }}</span>
                <span class="text-xs text-muted-foreground">Skipped</span>
              </CardContent>
            </Card>
          </div>

          <div v-if="isImportFinished && rowEvents.length > 0" class="flex flex-col gap-2">
            <span class="text-sm font-medium">Row issues ({{ rowEvents.length }})</span>
            <Card class="shadow-none">
              <ResponsiveTable rounded>
                <ResponsiveTableHeader>
                  <ResponsiveTableHead class="w-16">Row</ResponsiveTableHead>
                  <ResponsiveTableHead>Issue</ResponsiveTableHead>
                  <ResponsiveTableHead>Value</ResponsiveTableHead>
                </ResponsiveTableHeader>
                <ResponsiveTableBody>
                  <ResponsiveTableRow v-for="event in rowEvents" :key="`${event.row_number}-${event.validation_type}`">
                    <ResponsiveTableCell :cols="1" :cols-sm="1" label="Row" class="font-mono text-xs">
                      {{ event.row_number }}
                    </ResponsiveTableCell>
                    <ResponsiveTableCell :cols="3" :cols-sm="3" label="Issue" class="text-xs">
                      {{ event.hint }}
                    </ResponsiveTableCell>
                    <ResponsiveTableCell :cols="4" :cols-sm="4" label="Value" class="text-xs text-muted-foreground">
                      {{ event.input_value ?? '—' }}
                    </ResponsiveTableCell>
                  </ResponsiveTableRow>
                </ResponsiveTableBody>
              </ResponsiveTable>
            </Card>
          </div>
        </div>

        <div class="flex justify-end gap-2">
          <Button type="button" variant="outline" :disabled="!isImportFinished" @click="backToTable">
            Back to Users
          </Button>
          <Button v-if="isImportFinished" type="button" @click="startAnotherImport">Import Another File</Button>
        </div>
      </template>
    </DialogContent>
  </Dialog>
</template>

<script setup lang="ts">
import SpinnerSvg from '~/assets/icons/spinner.svg';
import { CircleCheckIcon, CircleXIcon, FileUpIcon, Search, UserPlusIcon, XIcon } from 'lucide-vue-next';
import {
  getLatestCanvassingAppUsersImport,
  getProjectCanvassingAppUsers,
  startCanvassingAppUsersImport,
} from '~/client';
import type { CanvassingApplicationName } from '~/client';
import { canvasserName } from '~/utils/canvassing/format';

const props = withDefaults(
  defineProps<{
    projectId: string;
    // Gates the Add/Import actions: users can be previewed once a project is picked, but adding or
    // importing requires the canvassing app configuration to be saved first.
    canManageUsers?: boolean;
    // Currently-picked canvassing app + org ids. When set, the preview lists users for this
    // selection instead of the project's saved config, so a picked-but-unsaved project still
    // shows its users.
    appName?: CanvassingApplicationName;
    appIds?: string[];
  }>(),
  { canManageUsers: true, appName: undefined, appIds: () => [] }
);

const Spinner = SpinnerSvg;
const isOpen = ref<boolean>(false);
const view = ref<'table' | 'upload' | 'progress'>('table');

// Pagination/search are kept in local state (not the URL): this modal lives on the project-edit
// form, whose NavigationGuard intercepts `onBeforeRouteUpdate`, so URL-driven paging would trip the
// unsaved-changes prompt instead of changing the page.
const page = ref(1);
const size = ref(10);
const search = ref('');
const debouncedSearch = ref('');
// Debounce the search term and reset to the first page when it settles, so results aren't stuck on
// a now-empty high page number.
watchDebounced(
  search,
  (value) => {
    debouncedSearch.value = value;
    page.value = 1;
  },
  { debounce: 300 }
);

// Override the saved config only when a selection is actually picked; the endpoint needs both the
// app name and at least one org id (Pulsar has no picker, so it falls through to the saved config).
const selectionOverride = computed(() =>
  props.appName && props.appIds.length ? { app_name: props.appName, app_ids: props.appIds } : {}
);
const params = computed(() => ({
  page: page.value,
  size: size.value,
  search: debouncedSearch.value || undefined,
  ...selectionOverride.value,
}));

const {
  data: usersResponse,
  error: usersError,
  isLoading: isLoadingUsers,
  refetch: refetchUsers,
} = useQuery({
  key: () => ['project-canvassing-app-users', props.projectId, params.value],
  query: () =>
    getProjectCanvassingAppUsers({
      composable: '$fetch',
      path: { project_id: props.projectId },
      query: params.value,
    }),
  enabled: () => isOpen.value && !!props.projectId,
  staleTime: 0,
  placeholderData: (previousData) => previousData,
});

const items = computed(() => usersResponse.value?.items ?? []);
const totalCount = computed(() => usersResponse.value?.total_count ?? 0);
// `isLoading` is true on every refetch (incl. page changes), but `placeholderData` keeps the
// previous page visible meanwhile — so only show the full loader on the very first load, otherwise
// the table would blink out and back on each page change.
const isInitialUsersLoad = computed(() => isLoadingUsers.value && !usersResponse.value);

// The single source of truth for the import state: the project's latest import.
// Powers resume-on-open, the disabled Import button, and the progress/summary view.
const { data: latestResponse, refetch: refetchLatest } = useQuery({
  key: () => ['canvassing-app-users-latest-import', props.projectId],
  query: () => getLatestCanvassingAppUsersImport({ composable: '$fetch', path: { project_id: props.projectId } }),
  enabled: () => isOpen.value && !!props.projectId,
  staleTime: 0,
});

const latestImport = computed(() => latestResponse.value?.latest_import ?? null);
const importStatus = computed(() => latestImport.value?.status ?? null);
const importError = computed(() => latestImport.value?.error_message ?? null);
const hasActiveImport = computed(() => importStatus.value === 'PENDING' || importStatus.value === 'PROCESSING');
const importButtonTitle = computed(() => {
  if (!props.canManageUsers) return 'Save the configuration to import users';
  if (hasActiveImport.value) return 'An import is already in progress';
  return undefined;
});
const isImportFinished = computed(() => importStatus.value === 'SUCCESS' || importStatus.value === 'FAILED');
const hasCounts = computed(() => latestImport.value?.all_rows_count != null);
const rowEvents = computed(() => latestImport.value?.row_events ?? []);

// Resume: whenever an active import is visible while the modal is open (on open or right
// after starting one), show its progress.
watch(hasActiveImport, (active) => {
  if (active && isOpen.value) view.value = 'progress';
});

useTimeoutPoll(
  async () => {
    if (!isOpen.value || !hasActiveImport.value) return;
    await refetchLatest().catch(() => undefined);
    if (isImportFinished.value) await refetchUsers().catch(() => undefined);
  },
  5000,
  { immediate: true }
);

// Upload form state.
const s3Url = ref('');
const fileName = ref('');
const isSubmitting = ref(false);

function onFileUploaded(data: { privateUrl: string; publicUrl: string; fileName: string } | null) {
  s3Url.value = data?.privateUrl ?? '';
  fileName.value = data?.fileName ?? '';
}

async function submitImport() {
  if (!s3Url.value) return;
  isSubmitting.value = true;
  try {
    await startCanvassingAppUsersImport({
      composable: '$fetch',
      path: { project_id: props.projectId },
      body: { s3_url: s3Url.value, file_name: fileName.value },
    });
    view.value = 'progress';
    await refetchLatest().catch(() => undefined);
  } catch (error) {
    showToastError(error instanceof Error ? error : 'Failed to start import');
  } finally {
    isSubmitting.value = false;
  }
}

function resetUpload() {
  s3Url.value = '';
  fileName.value = '';
}

function backToTable() {
  view.value = 'table';
  resetUpload();
  refetchUsers().catch(() => undefined);
}

function startAnotherImport() {
  resetUpload();
  view.value = 'upload';
}

// Reset to the users table and clear any half-finished upload whenever the modal closes, so the
// next open always starts clean.
function onOpenChange(open: boolean) {
  if (!open) {
    view.value = 'table';
    resetUpload();
    page.value = 1;
    search.value = '';
  }
}
</script>
