import * as z from 'zod';

export interface SurveyGoalOptions {
  isDraft: boolean;
}

//Backend accepts survey_goal_percentage > 0 only
export const schemaObject = {
  survey_goal_percentage: z
    .string()
    .optional()
    .transform((val) => {
      if (val == null || val.trim() === '') return undefined;
      return Number(val.trim().replaceAll(',', ''));
    })
    .refine((n) => n === undefined || !Number.isNaN(n), { message: 'Survey Goal Percentage must be a valid number' })
    .refine((n) => n === undefined || Number.isFinite(n), {
      message: 'Survey Goal Percentage must be a finite number',
    })
    .refine((n) => n === undefined || n <= 100, {
      message: 'Survey Goal Percentage must be less than or equal to 100',
    }),
};

type SurveyGoalData = z.infer<z.ZodObject<typeof schemaObject>>;

export function addSurveyGoalIssues(data: SurveyGoalData, ctx: z.RefinementCtx, { isDraft }: SurveyGoalOptions) {
  if (isDraft) return;

  if (data.survey_goal_percentage === undefined) {
    ctx.addIssue({
      path: ['survey_goal_percentage'],
      code: z.ZodIssueCode.custom,
      message: 'Survey Goal Percentage is required',
    });
  }

  if (data.survey_goal_percentage !== undefined && data.survey_goal_percentage <= 0) {
    ctx.addIssue({
      path: ['survey_goal_percentage'],
      code: z.ZodIssueCode.custom,
      message: 'Survey Goal Percentage must be greater than 0',
    });
  }
}

export function buildSurveyGoalPayload(values: SurveyGoalData): { survey_goal_percentage: number | null } {
  return {
    survey_goal_percentage:
      typeof values.survey_goal_percentage === 'number' && Number.isFinite(values.survey_goal_percentage)
        ? values.survey_goal_percentage
        : 0,
  };
}
