import * as z from 'zod';
import { toTypedSchema } from '@vee-validate/zod';
import type { ProjectStaffingStatus } from '~/client';

export interface StaffingOptions {
  isDraft: boolean;
}

const staffingGoalSchema = z
  .string({ invalid_type_error: 'Staffing goal must be a string' })
  .trim()
  .optional()
  .transform((s) => (s && s.length > 0 ? Number(s.replaceAll(',', '')) : undefined))
  .refine((n) => n === undefined || !Number.isNaN(n), { message: 'Staffing goal must be a valid number' })
  .refine((n) => n === undefined || Number.isFinite(n), { message: 'Staffing goal must be a finite number' });

const staffingStatusSchema = z
  .string()
  .optional()
  .transform((val) => (val ? (val as ProjectStaffingStatus) : undefined));

export const schemaObject = {
  staffing_goal: staffingGoalSchema,
  staffing_status: staffingStatusSchema,
};

type StaffingData = z.infer<z.ZodObject<typeof schemaObject>>;

export function addStaffingIssues(data: StaffingData, ctx: z.RefinementCtx, { isDraft }: StaffingOptions) {
  if (isDraft) return;

  if (data.staffing_goal === undefined) {
    ctx.addIssue({
      path: ['staffing_goal'],
      code: z.ZodIssueCode.custom,
      message: 'Staffing goal is required',
    });
  } else if (!(data.staffing_goal > 0)) {
    ctx.addIssue({
      path: ['staffing_goal'],
      code: z.ZodIssueCode.custom,
      message: 'Staffing goal must be greater than 0',
    });
  }

  if (!data.staffing_status) {
    ctx.addIssue({
      path: ['staffing_status'],
      code: z.ZodIssueCode.custom,
      message: 'Staffing Status is required',
    });
  }
}

export function buildStaffingPayload(values: StaffingData): {
  staffing_goal: number;
  staffing_status: ProjectStaffingStatus;
} {
  return {
    staffing_goal:
      typeof values.staffing_goal === 'number' && Number.isFinite(values.staffing_goal) ? values.staffing_goal : 0,
    staffing_status: values.staffing_status ?? 'finished',
  };
}

export const formSchema = toTypedSchema(
  z.object(schemaObject).superRefine((data, ctx) => addStaffingIssues(data, ctx, { isDraft: false }))
);
