import * as z from 'zod';
import type { CanvassingApplicationName, NuminarSyncSource } from '~/client';

// Keep the runtime Zod enum in lock-step with the generated NuminarSyncSource union.
const NUMINAR_SOURCES = ['api', 's3'] as const satisfies readonly NuminarSyncSource[];

export interface CanvassingAppOptions {
  isDraft: boolean;
}

export const I360_DEFAULT_PREFIX_SENTINEL = '__default__';

export const prefixToSelectValue = (prefix: string): string => (prefix === '' ? I360_DEFAULT_PREFIX_SENTINEL : prefix);

export const selectValueToPrefix = (value: string | undefined | null): string =>
  value === I360_DEFAULT_PREFIX_SENTINEL || value == null ? '' : value;

export const schemaObject = {
  canvassing_application_name: z
    .string()
    .optional()
    .transform((val) => (val ? (val as CanvassingApplicationName) : undefined)),
  canvassing_application_ids: z.array(z.record(z.string(), z.array(z.string()))).optional(),
  i360_file_prefix: z.string().optional(),
  pulsar_api_key: z.string().optional(),
  numinar_source: z.enum(NUMINAR_SOURCES).optional(),
  numinar_file_prefix: z.string().optional(),
};

type CanvassingAppData = z.infer<z.ZodObject<typeof schemaObject>>;

export function addCanvassingAppIssues(
  data: CanvassingAppData,
  ctx: z.RefinementCtx,
  { isDraft }: CanvassingAppOptions
) {
  if (isDraft) return;

  if (!data.canvassing_application_name) {
    ctx.addIssue({
      message: 'Canvassing App is required',
      code: z.ZodIssueCode.custom,
      path: ['canvassing_application_name'],
    });
  }

  // Pulsar authenticates with an API key and has no org/project ids to select.
  if (data.canvassing_application_name === 'pulsar') {
    return;
  }

  // Numinar S3 identifies the project by prefix (= org-id) — no org-id picking. It needs a prefix
  // instead of a project selection.
  if (data.canvassing_application_name === 'numinar' && data.numinar_source === 's3') {
    if (data.numinar_file_prefix === undefined) {
      ctx.addIssue({
        message: 'A Numinar prefix is required',
        code: z.ZodIssueCode.custom,
        path: ['numinar_file_prefix'],
      });
    }
    return;
  }

  if (!data.canvassing_application_ids || data.canvassing_application_ids.length === 0) {
    ctx.addIssue({
      message: 'At least one Project should be selected',
      code: z.ZodIssueCode.custom,
      path: ['canvassing_application_ids'],
    });
    return;
  }

  if (
    data.canvassing_application_name &&
    data.canvassing_application_name !== 'i360' &&
    data.canvassing_application_ids.length > 1
  ) {
    ctx.addIssue({
      message: 'Multiple project selection is available only for the i360 application',
      code: z.ZodIssueCode.custom,
      path: ['canvassing_application_ids'],
    });
  }
}

export function buildCanvassingAppPayload(values: CanvassingAppData): {
  canvassing_application_name: CanvassingApplicationName | null;
  canvassing_application_ids: { 'org-id': string[] } | null;
  i360_file_prefix: string | null;
  pulsar_api_key: string | null;
  numinar_source: NuminarSyncSource | null;
  numinar_file_prefix: string | null;
} {
  const flattened = values.canvassing_application_ids?.flatMap((item) => item['org-id']) ?? [];
  const isNuminar = values.canvassing_application_name === 'numinar';
  const isNuminarS3 = isNuminar && values.numinar_source === 's3';
  return {
    canvassing_application_name: values.canvassing_application_name ?? null,
    // Numinar S3 identifies the project by prefix, not org-id selection.
    canvassing_application_ids: !isNuminarS3 && flattened.length > 0 ? { 'org-id': flattened } : null,
    // Only meaningful for i360; the backend ignores it for other providers. The Select stores a
    // sentinel for the empty/default prefix — translate it back to ''.
    i360_file_prefix:
      values.canvassing_application_name === 'i360' ? selectValueToPrefix(values.i360_file_prefix) : null,
    // Write-only; sent only when the admin enters a value (Pulsar only). Null keeps the stored key.
    pulsar_api_key:
      values.canvassing_application_name === 'pulsar' && values.pulsar_api_key ? values.pulsar_api_key : null,
    // Numinar sync pipeline: 's3' (new, default) or 'api' (legacy). Null for other providers.
    numinar_source: isNuminar ? (values.numinar_source ?? 's3') : null,
    // The Numinar S3 prefix (= org-id). Sentinel translated back to ''. Null unless Numinar S3.
    numinar_file_prefix: isNuminarS3 ? selectValueToPrefix(values.numinar_file_prefix) : null,
  };
}
