import * as z from 'zod';
import { toTypedSchema } from '@vee-validate/zod';
import { schemaObject as voiceVerificationSchema, addVoiceVerificationIssues } from './projectVoiceVerification';
import { schemaObjectSignatures as paymentSchema, addSignaturePaymentIssues } from './projectPayment';
import { schemaObject as staffingSchema, addStaffingIssues } from './projectStaffing';
import { schemaObject as contractTemplatesSchema, addContractTemplateIssues } from './projectContractTemplates';
import { schemaObject as budgetSchema } from './projectBudget';

export const schemaObject = {
  ...voiceVerificationSchema,
  ...paymentSchema,
  ...staffingSchema,
  ...contractTemplatesSchema,
  ...budgetSchema,
};

export interface SignatureFormSchemaOptions {
  isDraft: boolean;
  deletedTemplateIds?: string[];
}

export function makeFormSchema({ isDraft, deletedTemplateIds = [] }: SignatureFormSchemaOptions) {
  const deletedTemplateIdSet = new Set(deletedTemplateIds);
  return toTypedSchema(
    z.object(schemaObject).superRefine((data, ctx) => {
      addContractTemplateIssues(data, ctx, { deletedTemplateIds: deletedTemplateIdSet });
      addSignaturePaymentIssues(data, ctx);
      addVoiceVerificationIssues(data, ctx);
      addStaffingIssues(data, ctx, { isDraft });
    })
  );
}
