import { createSelectorSurvey } from '~/client';
import type { CreateSurveyRequest, SurveySelectorItem } from '~/client';
import { showToastError, showToastSuccess } from '~/utils/show-toast';

export const useCreateCanvassingAppProject = defineMutation(() => {
  const queryCache = useQueryCache();

  const { mutateAsync, asyncStatus } = useMutation({
    mutation: (params: { data: CreateSurveyRequest }): Promise<SurveySelectorItem> =>
      createSelectorSurvey({
        composable: '$fetch',
        body: ref(params.data),
      }),
    onSuccess: () => {
      queryCache.invalidateQueries({ key: ['selector-surveys-list'] });
      showToastSuccess('Project created successfully');
    },
    onError(error) {
      showToastError(error);
    },
  });

  return {
    createCanvassingAppProject: mutateAsync,
    isCreatingCanvassingAppProject: computed(() => asyncStatus.value === 'loading'),
  };
});
