import { getContractTemplates } from '~/client';
import type { ContractProvider } from '~/client';

const DEFAULT_PROVIDER: ContractProvider = 'sign_well';

export const useSelectorContractTemplates = (provider: ContractProvider = DEFAULT_PROVIDER) => {
  const { data, isLoading, error, refetch } = useQuery({
    key: () => ['selector-contract-templates', provider],
    query: () => getContractTemplates({ composable: '$fetch', query: { provider } }),
  });

  return {
    contractTemplates: computed(() => data.value?.items ?? []),
    refetch,
    isLoading,
    error,
    provider,
  };
};
