export const percentMask = {
  number: { locale: 'en-US', fraction: 2, unsigned: true },
  preProcess: (val: string) => {
    let s = val.replace(/[^\d.,]/g, '').replace(',', '.');
    if (s === '.') return '0.';
    if (s.startsWith('.')) s = '0' + s;
    const endsWithDot = s.endsWith('.');
    const toParse = endsWithDot ? s.slice(0, -1) : s;
    if (!toParse) return s;
    const num = parseFloat(toParse);
    if (Number.isNaN(num)) return s;
    const clamped = Math.max(0, Math.min(100, num));
    return endsWithDot ? `${clamped}.` : String(clamped);
  },
  postProcess: (val: string) => (val ? `${val}` : ''),
};
