<template>
  <Dialog v-model:open="isOpen" @update:open="onOpenUpdate">
    <DialogTrigger as-child>
      <slot />
    </DialogTrigger>
    <DialogContent class="gap-6">
      <DialogHeader>
        <DialogTitle>Create New Canvassing Project Entry</DialogTitle>
        <DialogDescription>
          Add a project that exists in the canvassing app but is not in the list yet.
        </DialogDescription>
      </DialogHeader>
      <form id="createCanvassingAppProject" class="flex flex-col gap-4" @submit.prevent="onSubmit">
        <FormItemWrapper name="name" label="Project Name" is-required>
          <template #default="{ slots }">
            <Input
              id="canvassing-app-project-name"
              data-testid="canvassing-app-project-name-input"
              type="text"
              placeholder="My Project"
              v-bind="slots.componentField"
              :disabled="isCreatingCanvassingAppProject"
            />
          </template>
        </FormItemWrapper>
        <FormItemWrapper name="id" label="Project ID" is-required>
          <template #default="{ slots }">
            <Input
              id="canvassing-app-project-id"
              data-testid="canvassing-app-project-id-input"
              type="text"
              placeholder="Enter the canvassing app project ID"
              v-bind="slots.componentField"
              :disabled="isCreatingCanvassingAppProject"
            />
          </template>
        </FormItemWrapper>
      </form>
      <DialogFooter class="flex flex-row justify-end gap-2">
        <DialogClose as-child>
          <Button variant="outline" class="h-10 px-4" :disabled="isCreatingCanvassingAppProject">Cancel</Button>
        </DialogClose>
        <Button
          type="submit"
          form="createCanvassingAppProject"
          data-testid="canvassing-app-project-submit"
          :loading="isCreatingCanvassingAppProject"
        >
          Create
        </Button>
      </DialogFooter>
    </DialogContent>
  </Dialog>
</template>

<script setup lang="ts">
import { toTypedSchema } from '@vee-validate/zod';
import { useForm } from 'vee-validate';
import type { CanvassingApplicationName, SurveySelectorItem } from '~/client';
import { canvassingAppProjectCreateSchema } from '~/constants/validationSchemas/canvassingAppProjectCreate';
import { useCreateCanvassingAppProject } from '~/mutations/project/createCanvassingAppProject';

const props = defineProps<{
  appName: CanvassingApplicationName;
}>();

const emit = defineEmits<{
  created: [item: SurveySelectorItem];
}>();

const isOpen = ref<boolean>(false);

const { createCanvassingAppProject, isCreatingCanvassingAppProject } = useCreateCanvassingAppProject();

const { handleSubmit, resetForm } = useForm({
  validationSchema: toTypedSchema(canvassingAppProjectCreateSchema),
});

const onSubmit = handleSubmit(async (values) => {
  const item = await createCanvassingAppProject({
    data: { app_name: props.appName, id: values.id, name: values.name },
  });
  emit('created', item);
  isOpen.value = false;
});

function onOpenUpdate(open: boolean) {
  if (!open) resetForm();
}
</script>
