import * as z from 'zod';
import { toTypedSchema } from '@vee-validate/zod';
import { schemaObject as canvassingAppSchema, addCanvassingAppIssues } from './projectCanvassingApp';
import { schemaObjectCanvassing as paymentSchema, addCanvassingPaymentIssues } from './projectPayment';
import { schemaObject as staffingSchema, addStaffingIssues } from './projectStaffing';
import { schemaObject as surveySchema, addSurveyGoalIssues } from './survey';
import { schemaObject as voiceRecording, addVoiceRecordingIssues } from './projectVoiceRecording';
import { schemaObject as contractTemplatesSchema, addContractTemplateIssues } from './projectContractTemplates';
import { schemaObject as budgetSchema } from './projectBudget';

export const schemaObject = {
  ...canvassingAppSchema,
  ...paymentSchema,
  ...staffingSchema,
  ...surveySchema,
  ...voiceRecording,
  ...contractTemplatesSchema,
  ...budgetSchema,
};

export interface CanvassingFormSchemaOptions {
  isDraft: boolean;
  deletedTemplateIds?: string[];
}

export function makeFormSchema({ isDraft, deletedTemplateIds = [] }: CanvassingFormSchemaOptions) {
  const deletedTemplateIdSet = new Set(deletedTemplateIds);
  return toTypedSchema(
    z.object(schemaObject).superRefine((data, ctx) => {
      addContractTemplateIssues(data, ctx, { deletedTemplateIds: deletedTemplateIdSet });
      addCanvassingAppIssues(data, ctx, { isDraft });
      addVoiceRecordingIssues(data, ctx, { isDraft });
      addCanvassingPaymentIssues(data, ctx);
      addStaffingIssues(data, ctx, { isDraft });
      addSurveyGoalIssues(data, ctx, { isDraft });
    })
  );
}
