<template>
  <form id="editProjectConfigurationFormCanvassing" class="flex flex-col gap-4 pb-4" @submit="onSubmit">
    <ProjectEditConfigurationSection
      section-id="staffing"
      title="Staffing"
      intro="How many canvassers you plan to onboard, and whether the project is actively recruiting."
      :state="states.staffing"
    >
      <ProjectEditConfigurationStaffingSection />
    </ProjectEditConfigurationSection>

    <ProjectEditConfigurationSection
      section-id="contracts"
      title="Contracts"
      intro="Default contract templates sent to canvassers when they're onboarded to this project."
      :state="states.contracts"
    >
      <ProjectEditConfigurationContractTemplatesCard :deleted-templates="deletedContractTemplates" />
    </ProjectEditConfigurationSection>

    <ProjectEditConfigurationSection
      section-id="payment"
      title="Payment"
      intro="Per-hour rates and time-tracking rules. Changes apply to new assignments only."
      :state="states.payment"
    >
      <SectionPayment :saved-pricing="data?.pricing" />
    </ProjectEditConfigurationSection>

    <ProjectEditConfigurationSection
      section-id="budget"
      title="Project Budget"
      intro="Total budget agreed in the contract and how much has been received from the client."
      :state="states.budget"
    >
      <ProjectEditConfigurationBudgetSection />
    </ProjectEditConfigurationSection>

    <ProjectEditConfigurationSection
      section-id="voice"
      title="Note-taking"
      intro="Whether and where canvassers take notes on conversations in the field."
      :state="states.voice"
    >
      <SectionVoice :project-id="projectId" :saved-restricted-zip-codes="data?.restricted_zip_codes" />
    </ProjectEditConfigurationSection>

    <ProjectEditConfigurationSection
      section-id="app"
      title="Canvassing App"
      intro="Which third-party canvassing platform powers this project and which surveys it pulls from."
      :state="states.app"
    >
      <SectionApp :is-draft="isDraft" :config="data?.canvassing_application_config" :project-id="projectId" />
    </ProjectEditConfigurationSection>

    <ProjectEditConfigurationSection
      section-id="goal"
      title="Goal"
      intro="Target survey completion percentage for the project."
      :state="states.goal"
    >
      <SectionGoal />
    </ProjectEditConfigurationSection>

    <ProjectEditConfigurationStickyBar
      :edited-count="editedCount"
      :invalid-count="invalidCount"
      :is-loading="isEditProjectConfigurationLoading"
      @save="onSubmit"
      @discard="onDiscard"
    />

    <NavigationGuard
      v-if="processedPassedData && data && isAuthenticated"
      :saved-data="processedPassedData"
      :changed-data="processedDataFromForm"
      title="Warning"
      description="You have some unsaved changes on this tab! Save them before switching to another tab."
      confirm-text="Discard Changes"
    />
  </form>
</template>

<script setup lang="ts">
import { useForm } from 'vee-validate';
import type { CanvassingProjectConfiguration, ContractConfigs } from '~/types/projects/configuration';
import { useEditProjectConfiguration } from '~/mutations/project/edit/configuration';
import { makeFormSchema as makeCanvassingFormSchema } from '~/constants/validationSchemas/projectEditConfigurationCanvassing';
import { buildStaffingPayload } from '~/constants/validationSchemas/projectStaffing';
import { buildVoiceRecordingPayload } from '~/constants/validationSchemas/projectVoiceRecording';
import { buildCanvassingAppPayload, prefixToSelectValue } from '~/constants/validationSchemas/projectCanvassingApp';
import { buildSurveyGoalPayload } from '~/constants/validationSchemas/survey';
import type {
  AudioRecordingPermission,
  CanvassingApplicationName,
  CanvassingProjectPricing,
  ProjectStaffing,
  ProjectStaffingStatus,
  ProjectStatus,
} from '~/client';
import {
  CANVASSING_FIELD_GATES,
  CANVASSING_FIELD_TO_SECTION,
  CANVASSING_SECTION_IDS,
  getCanvassingSectionStates,
  isFieldGatedOff,
  type CanvassingSectionId,
} from '~/utils/projectEditConfigurationSections';

interface Props {
  projectId: string;
  data: CanvassingProjectConfiguration | undefined;
  status: ProjectStatus | undefined;
}

const props = defineProps<Props>();

const { editProjectConfiguration, isEditProjectConfigurationLoading } = useEditProjectConfiguration();

const { isAuthenticated } = useUserRole();

const isDraft = computed(() => props.status === 'draft');

const deletedContractTemplates = computed(() => getDeletedContractTemplates(props.data?.contract_configs));

const { handleSubmit, setValues, setFieldValue, values, setFieldError, errors } = useForm({
  validationSchema: computed(() =>
    makeCanvassingFormSchema({
      isDraft: isDraft.value,
      deletedTemplateIds: deletedContractTemplates.value.map((t) => t.id),
    })
  ),
  initialValues: {},
  keepValuesOnUnmount: true,
});

const hasAttemptedSubmit = ref(false);
provide('liveValidate', hasAttemptedSubmit);

function checkContractTemplate(): boolean {
  if (values.contract_sending_enabled && !values.contract_template_local) {
    setFieldError('contract_template_local', 'Contract Template is required');
    return false;
  }
  return true;
}

const onSubmit = handleSubmit(
  async (values) => {
    if (!checkContractTemplate()) {
      showToastError('Please fix the highlighted fields and try again.', 'Form validation failed.');
      return;
    }
    const paymentsEnabled = values.payments_enabled || false;
    const isIncreasedPayRateEnabled = !!paymentsEnabled && !!values.increased_pay_rate_enabled;
    const threshold = isIncreasedPayRateEnabled
      ? typeof values.increased_pay_rate_threshold_in_hours === 'number'
        ? values.increased_pay_rate_threshold_in_hours
        : 0
      : (props.data?.pricing.increased_pay_rate_threshold_in_hours ?? 0); //same source due to we have 1 input for now for this values
    const processedPricing: CanvassingProjectPricing = {
      for_canvasser_per_hour: paymentsEnabled ? (values.for_canvasser_per_hour ?? 0) : 0,
      qrf_for_canvasser_per_hour: paymentsEnabled ? (values.qrf_for_canvasser_per_hour ?? 0) : 0,
      earning_review_hours: values.earning_review_hours,
      allowed_break_minutes_per_hour: values.allowed_break_minutes_per_hour,
      grace_allowance_minutes: values.grace_allowance_minutes,
      increased_for_canvasser_per_hour: isIncreasedPayRateEnabled
        ? typeof values.increased_for_canvasser_per_hour === 'number'
          ? values.increased_for_canvasser_per_hour
          : 0
        : 0,
      increased_qrf_for_canvasser_per_hour: isIncreasedPayRateEnabled
        ? typeof values.increased_qrf_for_canvasser_per_hour === 'number'
          ? values.increased_qrf_for_canvasser_per_hour
          : 0
        : 0,
      increased_pay_rate_threshold_in_hours: threshold,
      increased_qrf_pay_rate_threshold_in_hours: threshold,
      increased_pay_rate_enabled: isIncreasedPayRateEnabled,
      payments_enabled: paymentsEnabled,
      travel_speed_config: {
        walk_speed_mph: values.walk_speed_mph,
        drive_speed_mph: values.drive_speed_mph,
      },
    };
    if (Object.values(processedPricing).some((value) => value === undefined)) {
      showToastError('Please check all fields are filled correctly.', 'Form validation failed.');
      return;
    }
    await editProjectConfiguration({
      data: {
        pricing: processedPricing,
        ...buildStaffingPayload(values),
        ...buildCanvassingAppPayload(values),
        voice_verification_enabled: false,
        ...buildSurveyGoalPayload(values),
        ...buildVoiceRecordingPayload(values),
        contract_configs: buildContractConfigsForSubmit(values),
        contract_sending_enabled: !!values.contract_sending_enabled,
        budget: {
          contract: toNumberOrNull(values.budget_contract),
          received: toNumberOrNull(values.budget_received),
        },
      },
      projectId: props.projectId,
    });
    // The Pulsar key is write-only; clear the transient input so it collapses back to the
    // "API key set" state and no longer counts as an unsaved edit.
    setFieldValue('pulsar_api_key', undefined, false);
  },
  () => {
    hasAttemptedSubmit.value = true;
    checkContractTemplate();
    showToastError('Please fix the highlighted fields and try again.', 'Form validation failed.');
  }
);

function applyInitialValuesFromProps() {
  if (!props.data) return;
  const { contractTemplateLocal, contractTemplateQrf, useSeparateQrf } = parseContractConfigs(
    props.data.contract_configs
  );
  setValues(
    {
      canvassing_application_name: props.data.canvassing_application_name || undefined,
      canvassing_application_ids: props.data.canvassing_application_ids
        ? props.data.canvassing_application_ids['org-id']?.map((item) => ({ 'org-id': [item] }))
        : undefined,
      i360_file_prefix:
        props.data.canvassing_application_config?.name === 'i360'
          ? prefixToSelectValue(props.data.canvassing_application_config.file_prefix ?? '')
          : undefined,
      numinar_source:
        props.data.canvassing_application_config?.name === 'numinar'
          ? (props.data.canvassing_application_config.source ?? 's3')
          : undefined,
      numinar_file_prefix:
        props.data.canvassing_application_config?.name === 'numinar' &&
        props.data.canvassing_application_config.source === 's3'
          ? prefixToSelectValue(props.data.canvassing_application_config.file_prefix ?? '')
          : undefined,
      payments_enabled: props.data.pricing.payments_enabled,
      increased_pay_rate_enabled: props.data.pricing.increased_pay_rate_enabled,
      for_canvasser_per_hour: props.data.pricing.for_canvasser_per_hour.toString(),
      staffing_status: props.data.staffing.status,
      staffing_goal: props.data.staffing.goal.toString() || undefined,
      survey_goal_percentage: props.data.survey_goal_percentage?.toString() || undefined,
      earning_review_hours: props.data.pricing.earning_review_hours.toString(),
      qrf_for_canvasser_per_hour: props.data.pricing.qrf_for_canvasser_per_hour.toString(),
      allowed_break_minutes_per_hour: props.data.pricing.allowed_break_minutes_per_hour.toString(),
      increased_for_canvasser_per_hour: props.data.pricing.increased_for_canvasser_per_hour?.toString() || undefined,
      increased_qrf_for_canvasser_per_hour:
        props.data.pricing.increased_qrf_for_canvasser_per_hour?.toString() || undefined,
      increased_pay_rate_threshold_in_hours:
        props.data.pricing.increased_pay_rate_threshold_in_hours?.toString() || undefined,
      grace_allowance_minutes: props.data.pricing.grace_allowance_minutes?.toString() || undefined,
      walk_speed_mph: props.data.pricing.travel_speed_config.walk_speed_mph.toString(),
      drive_speed_mph: props.data.pricing.travel_speed_config.drive_speed_mph.toString(),
      audio_recording: props.data.audio_recording || undefined,
      restricted_zip_codes: props.data.restricted_zip_codes || undefined,
      voter_redaction_enabled: !!props.data.voter_redaction_enabled,
      contract_template_local: contractTemplateLocal ?? undefined,
      contract_template_quick_response_force: contractTemplateQrf ?? undefined,
      use_separate_qrf_template: useSeparateQrf,
      contract_sending_enabled: !!props.data.contract_sending_enabled,
      budget_contract: props.data.budget.contract?.toString() ?? undefined,
      budget_received: props.data.budget.received?.toString() ?? undefined,
      // Write-only Pulsar key: never pre-filled, cleared on discard.
      pulsar_api_key: undefined,
    },
    false
  );
}

onMounted(applyInitialValuesFromProps);

function onDiscard() {
  applyInitialValuesFromProps();
}

const processedDataFromForm = computed(() => {
  const isIncreasedPayRateEnabled = !!values.payments_enabled && !!values.increased_pay_rate_enabled;
  const threshold =
    isIncreasedPayRateEnabled && values.increased_pay_rate_threshold_in_hours
      ? Number(values.increased_pay_rate_threshold_in_hours.replaceAll(',', ''))
      : props.data?.pricing.increased_pay_rate_threshold_in_hours;
  const processedPricing = {
    for_canvasser_per_hour: Number(values.for_canvasser_per_hour),
    earning_review_hours: values.earning_review_hours ? Number(values.earning_review_hours.replaceAll(',', '')) : null,
    qrf_for_canvasser_per_hour: values.qrf_for_canvasser_per_hour
      ? Number(values.qrf_for_canvasser_per_hour.replaceAll(',', ''))
      : null,
    allowed_break_minutes_per_hour: values.allowed_break_minutes_per_hour
      ? Number(values.allowed_break_minutes_per_hour.replaceAll(',', ''))
      : null,
    increased_for_canvasser_per_hour:
      isIncreasedPayRateEnabled && values.increased_for_canvasser_per_hour
        ? Number(values.increased_for_canvasser_per_hour.replaceAll(',', ''))
        : props.data?.pricing.increased_for_canvasser_per_hour,
    increased_qrf_for_canvasser_per_hour:
      isIncreasedPayRateEnabled && values.increased_qrf_for_canvasser_per_hour
        ? Number(values.increased_qrf_for_canvasser_per_hour.replaceAll(',', ''))
        : props.data?.pricing.increased_qrf_for_canvasser_per_hour,
    increased_pay_rate_threshold_in_hours: threshold,
    increased_qrf_pay_rate_threshold_in_hours: threshold,
    grace_allowance_minutes: values.grace_allowance_minutes
      ? Number(values.grace_allowance_minutes.replaceAll(',', ''))
      : null,
    travel_speed_config: {
      walk_speed_mph: values.walk_speed_mph ? Number(String(values.walk_speed_mph).replaceAll(',', '')) : null,
      drive_speed_mph: values.drive_speed_mph ? Number(String(values.drive_speed_mph).replaceAll(',', '')) : null,
    },
    increased_pay_rate_enabled: isIncreasedPayRateEnabled,
    payments_enabled: values.payments_enabled || false,
  };
  const applicationIds = values.canvassing_application_ids
    ? {
        'org-id': new Set(values.canvassing_application_ids?.flatMap((item) => item['org-id'])),
      }
    : null;
  return {
    pricing: processedPricing,
    staffing: {
      goal: values.staffing_goal ? Number(values.staffing_goal.replaceAll(',', '')) : null,
      status: values.staffing_status,
    },
    canvassing_application_ids: applicationIds || null,
    survey_goal_percentage:
      values.staffing_goal && values.survey_goal_percentage != null && values.survey_goal_percentage !== ''
        ? Number(values.survey_goal_percentage)
        : null,
    canvassing_application_name: values.canvassing_application_name || null,
    audio_recording: values.audio_recording || null,
    restricted_zip_codes: values.restricted_zip_codes ? new Set(values.restricted_zip_codes) : null,
    voter_redaction_enabled: !!values.voter_redaction_enabled,
    contract_template_local: values.contract_sending_enabled ? values.contract_template_local || null : null,
    contract_template_quick_response_force:
      values.contract_sending_enabled && values.use_separate_qrf_template
        ? values.contract_template_quick_response_force || null
        : null,
    use_separate_qrf_template: !!values.contract_sending_enabled && !!values.use_separate_qrf_template,
    contract_sending_enabled: !!values.contract_sending_enabled,
    budget: {
      contract: toNumberOrNull(values.budget_contract),
      received: toNumberOrNull(values.budget_received),
    },
  };
});

const processedPassedData = computed(() => {
  if (!props.data) return null;
  // contract_configs and canvassing_application_config are represented in the form by dedicated
  // fields (template selectors / app name + ids + prefix), not diffed as raw blobs — excluding
  // them keeps this saved snapshot key-symmetric with `processedDataFromForm` so the navigation
  // guard doesn't treat every canvassing project as permanently dirty.
  const { contract_configs: _, canvassing_application_config: __, ...rest } = props.data;
  const { contractTemplateLocal, contractTemplateQrf, useSeparateQrf } = parseContractConfigs(
    props.data.contract_configs
  );
  const contractsOn = !!props.data.contract_sending_enabled;
  return {
    ...rest,
    canvassing_application_ids: props.data.canvassing_application_ids
      ? { 'org-id': new Set(props.data.canvassing_application_ids['org-id']) }
      : null,
    restricted_zip_codes: props.data.restricted_zip_codes ? new Set(props.data.restricted_zip_codes) : null,
    contract_template_local: contractsOn ? contractTemplateLocal : null,
    contract_template_quick_response_force: contractsOn ? contractTemplateQrf : null,
    use_separate_qrf_template: contractsOn && useSeparateQrf,
  };
});

// ----- section state -----

function workingAsCanvassing(): CanvassingProjectConfiguration | null {
  if (!props.data) return null;
  return {
    pricing: {
      payments_enabled: values.payments_enabled || false,
      for_canvasser_per_hour: Number(values.for_canvasser_per_hour ?? 0),
      qrf_for_canvasser_per_hour: Number(values.qrf_for_canvasser_per_hour ?? 0),
      earning_review_hours: values.earning_review_hours
        ? Number(String(values.earning_review_hours).replaceAll(',', ''))
        : null,
      allowed_break_minutes_per_hour: values.allowed_break_minutes_per_hour
        ? Number(String(values.allowed_break_minutes_per_hour).replaceAll(',', ''))
        : null,
      grace_allowance_minutes: values.grace_allowance_minutes
        ? Number(String(values.grace_allowance_minutes).replaceAll(',', ''))
        : null,
      travel_speed_config: {
        walk_speed_mph: values.walk_speed_mph ? Number(String(values.walk_speed_mph).replaceAll(',', '')) : null,
        drive_speed_mph: values.drive_speed_mph ? Number(String(values.drive_speed_mph).replaceAll(',', '')) : null,
      },
      increased_pay_rate_enabled: !!values.payments_enabled && !!values.increased_pay_rate_enabled,
      increased_for_canvasser_per_hour: values.increased_for_canvasser_per_hour
        ? Number(String(values.increased_for_canvasser_per_hour).replaceAll(',', ''))
        : null,
      increased_qrf_for_canvasser_per_hour: values.increased_qrf_for_canvasser_per_hour
        ? Number(String(values.increased_qrf_for_canvasser_per_hour).replaceAll(',', ''))
        : null,
      increased_pay_rate_threshold_in_hours: values.increased_pay_rate_threshold_in_hours
        ? Number(String(values.increased_pay_rate_threshold_in_hours).replaceAll(',', ''))
        : null,
      increased_qrf_pay_rate_threshold_in_hours: values.increased_pay_rate_threshold_in_hours
        ? Number(String(values.increased_pay_rate_threshold_in_hours).replaceAll(',', ''))
        : null,
    } as CanvassingProjectPricing,
    staffing: {
      goal: values.staffing_goal ? Number(String(values.staffing_goal).replaceAll(',', '')) : null,
      status: (values.staffing_status as ProjectStaffingStatus) ?? props.data.staffing.status,
    } as ProjectStaffing,
    budget: {
      contract: toNumberOrNull(values.budget_contract),
      received: toNumberOrNull(values.budget_received),
    },
    canvassing_application_ids: values.canvassing_application_ids
      ? { 'org-id': (values.canvassing_application_ids as { 'org-id': string[] }[]).flatMap((item) => item['org-id']) }
      : null,
    canvassing_application_name: (values.canvassing_application_name as CanvassingApplicationName) ?? null,
    // The section-state diff works off the app name / ids / prefix form fields, not the raw config
    // blob, so pass the saved config through unchanged.
    canvassing_application_config: props.data.canvassing_application_config,
    survey_goal_percentage:
      values.survey_goal_percentage != null && values.survey_goal_percentage !== ''
        ? Number(values.survey_goal_percentage)
        : null,
    audio_recording: (values.audio_recording ?? null) as AudioRecordingPermission | null,
    restricted_zip_codes: values.restricted_zip_codes ?? null,
    voter_redaction_enabled: !!values.voter_redaction_enabled,
    contract_configs: buildContractConfigs(
      values.contract_template_local,
      values.contract_template_quick_response_force,
      !!values.use_separate_qrf_template
    ) as ContractConfigs,
    contract_sending_enabled: !!values.contract_sending_enabled,
  };
}

const invalidSections = computed(() => {
  const set = new Set<CanvassingSectionId>();
  for (const fieldName of Object.keys(errors.value ?? {})) {
    if (isFieldGatedOff(values, fieldName, CANVASSING_FIELD_GATES)) continue;
    const id = CANVASSING_FIELD_TO_SECTION[fieldName as keyof typeof CANVASSING_FIELD_TO_SECTION];
    if (id) set.add(id);
  }
  return set;
});

const disabledSections = computed(() => {
  const set = new Set<CanvassingSectionId>();
  if (!values.payments_enabled) set.add('payment');
  if (!values.contract_sending_enabled) set.add('contracts');
  return set;
});

const states = computed(() => {
  if (!props.data) {
    return CANVASSING_SECTION_IDS.reduce(
      (acc, id) => ({ ...acc, [id]: 'complete' as const }),
      {} as Record<CanvassingSectionId, 'complete'>
    );
  }
  const working = workingAsCanvassing() ?? props.data;
  const base = getCanvassingSectionStates({
    saved: props.data,
    working,
    invalidSections: invalidSections.value,
    disabledSections: disabledSections.value,
  });
  // The write-only Pulsar key isn't part of the saved config, so it can't be diffed.
  // A pending key entry marks the "app" section edited so the Save bar appears.
  if (values.pulsar_api_key) {
    base.app = invalidSections.value.has('app') ? 'edited-invalid' : 'edited';
  }
  return base;
});

const editedCount = computed(
  () => Object.values(states.value).filter((s) => s === 'edited' || s === 'edited-invalid').length
);
const invalidCount = computed(() => invalidSections.value.size);
</script>
