import type { AudioRecordingPermission } from '~/client';

const audioRecordingPermissionConfig: Record<AudioRecordingPermission, { label: string }> = {
  full_recording: { label: 'Full Note-taking' },
  full_recording_with_restricted_area: { label: 'Note-taking With Restricted Areas' },
  no_recording: { label: 'No Note-taking' },
};

export const voiceRecordingItems: SelectItem<AudioRecordingPermission>[] = Object.entries(
  audioRecordingPermissionConfig
).map(([value, { label }]) => ({ value: value as AudioRecordingPermission, name: label }));
