<template>
  <div
    v-if="isVisible"
    data-testid="project-edit-config-sticky-bar"
    class="sticky bottom-0 z-10 mt-5 flex items-center justify-between gap-4 rounded-lg border bg-background/95 backdrop-blur px-4 py-3 shadow-[0_-6px_16px_rgba(0,0,0,0.06)]"
  >
    <div class="flex items-center gap-2 text-sm font-medium text-warning-foreground">
      <span class="inline-block w-1.5 h-1.5 rounded-full bg-warning-foreground" />
      <span>{{ statusText }}</span>
    </div>
    <div class="flex gap-2">
      <Button
        type="button"
        variant="secondary"
        data-testid="project-edit-config-sticky-bar-discard"
        :disabled="isLoading || editedCount === 0"
        @click="$emit('discard')"
        >Discard</Button
      >
      <Button
        type="button"
        data-testid="project-edit-config-sticky-bar-save"
        :loading="isLoading"
        :disabled="invalidCount > 0 || editedCount === 0"
        @click="$emit('save')"
        >Save</Button
      >
    </div>
  </div>
</template>

<script setup lang="ts">
import { computed } from 'vue';
import { Button } from '~/components/ui/button';

interface Props {
  editedCount: number;
  invalidCount: number;
  isLoading: boolean;
}

const props = defineProps<Props>();
defineEmits<{ save: []; discard: [] }>();

const isVisible = computed(() => props.editedCount > 0 || props.invalidCount > 0);

const statusText = computed(() => {
  const parts: string[] = [];
  if (props.editedCount > 0) {
    parts.push(`${props.editedCount} section${props.editedCount === 1 ? '' : 's'} edited`);
  }
  if (props.invalidCount > 0) {
    parts.push(`${props.invalidCount} invalid`);
  }
  return parts.join(' · ');
});
</script>
