<template>
  <div>
    <Combobox
      multiple
      :model-value="selectedIndices"
      :class="cn('relative w-full', elementWidth)"
      :disabled="disabled"
      @update:model-value="(value: unknown) => onUpdateIndices(value as AcceptableValue[])"
    >
      <ComboboxAnchor as-child>
        <ComboboxTrigger :id="componentField?.name" as-child :disabled="loading">
          <Button variant="outline" class="justify-between h-10 w-full px-3 font-normal">
            <p v-if="loading">Loading items...</p>
            <span v-else class="flex items-center gap-1 overflow-hidden whitespace-nowrap">
              <template v-if="displayNames.length">
                <span
                  v-for="(chip, i) in displayNames.slice(0, maxItemsInInput)"
                  :key="i"
                  class="text-sm rounded-full px-2 py-0.5 border min-w-0 overflow-hidden text-ellipsis whitespace-nowrap"
                  :title="chip"
                >
                  {{ chip }}
                </span>

                <span v-if="displayNames.length > maxItemsInInput" class="text-xs text-muted-foreground flex-shrink-0">
                  +{{ displayNames.length - maxItemsInInput }}
                </span>
              </template>
              <span v-else class="text-muted-foreground">{{ placeholder }}</span>
            </span>
            <Spinner v-if="loading" class="!w-5 !h-5" />
            <ChevronsUpDown v-else class="ml-6 h-4 w-4 shrink-0 opacity-50" />
          </Button>
        </ComboboxTrigger>

        <ComboboxCancel class="absolute top-[0.75rem] end-10">
          <X
            v-if="(nullIsAll && fieldValue == null) || (!nullIsAll && Array.isArray(fieldValue) && fieldValue.length)"
            class="h-4 w-4 shrink-0 opacity-50"
            @click.stop.prevent="clearSelection"
          />
        </ComboboxCancel>
      </ComboboxAnchor>

      <ComboboxList class="max-h-[min(20rem,_calc(var(--reka-combobox-content-available-height)-10px))] relative z-0">
        <div class="sticky top-[-1px] z-50 bg-white rounded-lg">
          <div class="relative w-full items-center">
            <ComboboxInput
              class="pl-9 focus-visible:ring-0 border-0 border-b rounded-none h-10"
              :placeholder="inputPlaceholder"
              :display-value="() => ''"
            />
            <span class="absolute start-0 inset-y-0 flex items-center justify-center px-3">
              <Search class="size-4 text-muted-foreground" />
            </span>
          </div>
        </div>

        <ComboboxEmpty>{{ emptyText }}</ComboboxEmpty>

        <ComboboxGroup class="overflow-y-auto">
          <ComboboxItem v-if="nullIsAll" :value="0" :text-value="placeholder" @click.stop.prevent="selectAll()">
            {{ placeholder }}
            <ComboboxItemIndicator>
              <Check v-if="fieldValue == null" class="ml-auto h-4 w-4" />
            </ComboboxItemIndicator>
          </ComboboxItem>

          <ComboboxItem
            v-for="(item, i) in items"
            :key="i"
            :value="i + baseOffset"
            :text-value="item.name ?? stringify(item.value)"
            @click.stop="toggleByIdx(i)"
          >
            <span class="truncate">{{ item.name ?? stringify(item.value) }}</span>
            <ComboboxItemIndicator>
              <Check :class="cn('ml-auto h-4 w-4')" />
            </ComboboxItemIndicator>
          </ComboboxItem>
        </ComboboxGroup>
      </ComboboxList>
    </Combobox>

    <p v-if="error" class="p-2 text-sm text-destructive select-none">{{ error }}</p>
  </div>
</template>

<script lang="ts" setup>
import type { ComponentFieldBindingObject } from 'vee-validate';
import { Check, ChevronsUpDown, Search, X } from 'lucide-vue-next';
import { cn } from '@/lib/utils';
import type { AcceptableValue } from 'reka-ui';
import { isEqual } from 'lodash';
import { Spinner } from '~/assets/icons';

interface SelectItem<T> {
  name?: string;
  value: T;
}

interface Props {
  items: SelectItem<string | number | Record<string, any> | null>[];
  placeholder?: string;
  inputPlaceholder?: string;
  emptyText?: string;
  elementWidth?: string;
  nullIsAll: boolean;
  componentField: ComponentFieldBindingObject;
  disabled?: boolean;
  loading?: boolean;
  error?: string;
  maxItemsInInput?: number;
}

const props = withDefaults(defineProps<Props>(), {
  placeholder: 'Select…',
  inputPlaceholder: 'Search…',
  emptyText: 'No results found.',
  elementWidth: undefined,
  disabled: false,
  error: undefined,
  maxItemsInInput: 2,
});

const baseOffset = computed(() => (props.nullIsAll ? 1 : 0));

const fieldValue = computed<any>({
  get: () => props.componentField?.modelValue,
  set: (v) => props.componentField?.onChange?.(v),
});

const stringify = (v: any) => (typeof v === 'object' ? JSON.stringify(v) : String(v));

const selectedIndices = computed<number[] | null>(() => {
  if (props.nullIsAll && fieldValue.value == null) {
    return [0];
  }
  const arr: any[] = Array.isArray(fieldValue.value) ? fieldValue.value : [];
  const idxs = arr
    .map((val) => props.items.findIndex((it) => isEqual(it.value, val)))
    .filter((i) => i >= 0)
    .map((i) => i + baseOffset.value);
  return idxs;
});

function onUpdateIndices(indices: AcceptableValue[]) {
  if (!indices || indices.length === 0) {
    fieldValue.value = props.nullIsAll ? null : [];
    return;
  }

  if (props.nullIsAll && indices.includes(0)) {
    fieldValue.value = null;
    return;
  }

  const vals = indices
    .filter((i) => typeof i === 'number')
    .map((i) => i - baseOffset.value)
    .filter((i) => i >= 0 && i < props.items.length)
    .map((i) => props.items[i].value);

  if (props.nullIsAll && vals.length === props.items.length) {
    fieldValue.value = null;
  } else {
    fieldValue.value = vals;
  }
}

function toggleByIdx(i: number) {
  if (props.nullIsAll && fieldValue.value == null) {
    fieldValue.value = [props.items[i].value];
    return;
  }

  const current: any[] = Array.isArray(fieldValue.value) ? [...fieldValue.value] : [];
  const pos = current.findIndex((v) => isEqual(v, props.items[i].value));
  if (pos >= 0) current.splice(pos, 1);
  else current.push(props.items[i].value);

  if (props.nullIsAll && current.length === props.items.length) {
    fieldValue.value = null;
  } else {
    fieldValue.value = current;
  }
}

function selectAll() {
  if (props.nullIsAll) fieldValue.value = null;
}

function clearSelection() {
  fieldValue.value = props.nullIsAll ? null : [];
}

const displayNames = computed<string[]>(() => {
  if (props.nullIsAll && fieldValue.value == null) return [props.placeholder ?? 'All'];
  const current: any[] = Array.isArray(fieldValue.value) ? fieldValue.value : [];
  return current
    .map((v) => props.items.find((it) => isEqual(it.value, v))?.name ?? stringify(v))
    .filter(Boolean) as string[];
});
</script>

<style scoped></style>
